kam_report_config:
{
  "reportType": "INTERNAL_PERF_GMV_ATTRIBUTION",
  "externalReportType": "GMV_ATTRIBUTION_REPORT",
  "visibility": "INTERNAL_PERFORMANCE",
  "filterTags": [
    "report_group:roas",
    "report_group:bu"
  ],
  "externalRequiredFilters": [],
  "description": "Marketplace-level PROGRAM (ad-attributed) vs SITE (organic) funnel for a single period: a one-row aggregate across every seller of the agency. PROGRAM metrics come from per-click-timestamp attribution in client_vendor_channel_performance_facts; SITE metrics are correlated subqueries over monetize_merchant_facts. Spend and revenue are converted to the marketplace currency. Request `spend` alone for the total program-spend check. NOTE: `channel` is a FILTER-ONLY attribute -- this template has no __ATTRIBUTES__ placeholder, so channel can be filtered (PLA = os_product_ads, Display = guaranteed_display_ads / auction_display_ads) but never grouped by. The report is single-period; fetch current and baseline separately.",
  "source": "GOOGLE_BIG_QUERY",
  "sourceInfo": {
    "appKey": "GCP_BQ_KAM_CREDENTIALS"
  },
  "cacheInfo": {
    "isCachingEnabled": true,
    "cachingExpiryInSec": 900
  },
  "attributes": {
    "channel": {
      "key": "channel",
      "selector": "cvcpf.channel",
      "type": "STRING",
      "externalColumnName": "channel",
      "description": "Program (ad) channel: os_product_ads (PLA), guaranteed_display_ads / auction_display_ads (Display). Use as a filter to scope the PROGRAM attribution to a program type; SITE (organic) metrics are unaffected.",
      "filterTags": [
        "report_group:roas",
        "report_group:bu"
      ]
    }
  },
  "metrics": {
    "spend": {
      "key": "spend",
      "selector": "COALESCE(SUM(CASE WHEN cvcpf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN cvcpf.cost * scc.conversion_factor ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "spend",
      "description": "Total program (advertising) spend over the period, converted to the marketplace currency.",
      "filterTags": [
        "report_group:roas",
        "report_group:bu"
      ]
    },
    "impressions": {
      "key": "impressions",
      "selector": "COALESCE(SUM(CASE WHEN cvcpf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN cvcpf.impressions ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "impressions",
      "description": "Program ad impressions over the period.",
      "filterTags": [
        "report_group:roas",
        "report_group:bu"
      ]
    },
    "clicks": {
      "key": "clicks",
      "selector": "COALESCE(SUM(CASE WHEN cvcpf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN cvcpf.clicks ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "clicks",
      "description": "Program ad clicks over the period.",
      "filterTags": [
        "report_group:roas",
        "report_group:bu"
      ]
    },
    "program_gmv": {
      "key": "program_gmv",
      "selector": "COALESCE(SUM(CASE WHEN cvcpf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN cvcpf.program_per_click_timestamp_sales ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "program_gmv",
      "description": "Ad-attributed GMV (program sales), per-click-timestamp attribution, in source units.",
      "filterTags": [
        "report_group:roas",
        "report_group:bu"
      ]
    },
    "program_orders": {
      "key": "program_orders",
      "selector": "COALESCE(SUM(CASE WHEN cvcpf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN cvcpf.program_per_click_timestamp_conversions ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "program_orders",
      "description": "Ad-attributed orders (program conversions), per-click-timestamp attribution.",
      "filterTags": [
        "report_group:roas",
        "report_group:bu"
      ]
    },
    "program_viewproducts": {
      "key": "program_viewproducts",
      "selector": "COALESCE(SUM(CASE WHEN cvcpf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN cvcpf.program_per_click_timestamp_viewproduct ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "program_viewproducts",
      "description": "Ad-attributed product views (program view-product events), per-click-timestamp attribution.",
      "filterTags": [
        "report_group:roas",
        "report_group:bu"
      ]
    },
    "program_add2carts": {
      "key": "program_add2carts",
      "selector": "COALESCE(SUM(CASE WHEN cvcpf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN cvcpf.program_per_click_timestamp_add_to_cart ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "program_add2carts",
      "description": "Ad-attributed add-to-cart events (program), per-click-timestamp attribution.",
      "filterTags": [
        "report_group:roas",
        "report_group:bu"
      ]
    },
    "site_revenue": {
      "key": "site_revenue",
      "selector": "COALESCE((SELECT SUM(mmf.total_sok_sales_usd * scc2.conversion_factor) FROM `prj-onlinesales-prod-01.reporting.monetize_merchant_facts` AS mmf INNER JOIN `prj-onlinesales-prod-01.reporting.marketplace_clients` AS mc2 ON mmf.agency_id = mc2.agency_id AND mmf.marketplace_client_id = mc2.marketplace_client_id INNER JOIN `prj-onlinesales-prod-01.reporting.static_currency_conversion` AS scc2 ON scc2.from_currency = 'USD' AND scc2.to_currency = mc2.currency WHERE mmf.agency_id = '__AGENCY_ID__' AND mmf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__'), 0)",
      "type": "FLOAT",
      "externalColumnName": "site_revenue",
      "description": "Total organic site GMV (total SOK sales) over the period, converted to the marketplace currency.",
      "filterTags": [
        "report_group:roas",
        "report_group:bu"
      ]
    },
    "site_orders": {
      "key": "site_orders",
      "selector": "COALESCE((SELECT SUM(mmf.total_sok_salecompletes) FROM `prj-onlinesales-prod-01.reporting.monetize_merchant_facts` AS mmf INNER JOIN `prj-onlinesales-prod-01.reporting.marketplace_clients` AS mc2 ON mmf.agency_id = mc2.agency_id AND mmf.marketplace_client_id = mc2.marketplace_client_id INNER JOIN `prj-onlinesales-prod-01.reporting.static_currency_conversion` AS scc2 ON scc2.from_currency = 'USD' AND scc2.to_currency = mc2.currency WHERE mmf.agency_id = '__AGENCY_ID__' AND mmf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__'), 0)",
      "type": "FLOAT",
      "externalColumnName": "site_orders",
      "description": "Total organic site orders (total SOK sale-completes) over the period.",
      "filterTags": [
        "report_group:roas",
        "report_group:bu"
      ]
    },
    "site_viewproducts": {
      "key": "site_viewproducts",
      "selector": "COALESCE((SELECT SUM(mmf.total_sok_viewproducts) FROM `prj-onlinesales-prod-01.reporting.monetize_merchant_facts` AS mmf INNER JOIN `prj-onlinesales-prod-01.reporting.marketplace_clients` AS mc2 ON mmf.agency_id = mc2.agency_id AND mmf.marketplace_client_id = mc2.marketplace_client_id INNER JOIN `prj-onlinesales-prod-01.reporting.static_currency_conversion` AS scc2 ON scc2.from_currency = 'USD' AND scc2.to_currency = mc2.currency WHERE mmf.agency_id = '__AGENCY_ID__' AND mmf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__'), 0)",
      "type": "FLOAT",
      "externalColumnName": "site_viewproducts",
      "description": "Total organic site product views (total SOK view-products) over the period.",
      "filterTags": [
        "report_group:roas",
        "report_group:bu"
      ]
    },
    "site_add2carts": {
      "key": "site_add2carts",
      "selector": "COALESCE((SELECT SUM(mmf.total_sok_add2carts) FROM `prj-onlinesales-prod-01.reporting.monetize_merchant_facts` AS mmf INNER JOIN `prj-onlinesales-prod-01.reporting.marketplace_clients` AS mc2 ON mmf.agency_id = mc2.agency_id AND mmf.marketplace_client_id = mc2.marketplace_client_id INNER JOIN `prj-onlinesales-prod-01.reporting.static_currency_conversion` AS scc2 ON scc2.from_currency = 'USD' AND scc2.to_currency = mc2.currency WHERE mmf.agency_id = '__AGENCY_ID__' AND mmf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__'), 0)",
      "type": "FLOAT",
      "externalColumnName": "site_add2carts",
      "description": "Total organic site add-to-cart events (total SOK add2carts) over the period.",
      "filterTags": [
        "report_group:roas",
        "report_group:bu"
      ]
    }
  },
  "dateRanges": {
    "count": 1,
    "dataAvailabilityDays": 90,
    "maxDataFetchDaysDuration": 31
  },
  "query": {
    "REPORTING": "SELECT __METRICS__ FROM `prj-onlinesales-prod-01.reporting.client_vendor_channel_performance_facts` AS cvcpf INNER JOIN `prj-onlinesales-prod-01.reporting.clients` AS clients ON clients.client_id = cvcpf.client_id AND clients.agency_id = '__AGENCY_ID__' INNER JOIN `prj-onlinesales-prod-01.reporting.marketplace_clients` AS mc ON mc.agency_id = clients.agency_id AND clients.client_id != mc.marketplace_client_id INNER JOIN `prj-onlinesales-prod-01.reporting.static_currency_conversion` AS scc ON scc.from_currency = cvcpf.currency AND scc.to_currency = mc.currency WHERE cvcpf.vendor = 'os_ads' AND cvcpf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' AND __FILTER__;",
    "MERCHANT": "",
    "GROUPED": ""
  },
  "application": "irisTestApplication"
}

{
  "reportType": "INTERNAL_PERF_DISPLAY_AD_UNIT",
  "externalReportType": "DISPLAY_AD_UNIT_PERFORMANCE_REPORT",
  "visibility": "INTERNAL_PERFORMANCE",
  "filterTags": [
    "report_group:bu",
    "report_group:rr"
  ],
  "externalRequiredFilters": [],
  "description": "Display ad-unit funnel for a marketplace over a period: requests, non-zero responses, response rate, impressions, clicks, marketplace-currency spend and revenue, and the program funnel events (view-product, add-to-cart, conversions). Group by ad_unit_name and/or page_type for the ad-unit and page-type breakdowns, or by date for the daily request / response trend used in budget-utilisation debugging. Pass a page_type NOT IN ('', 'NA') filter to reproduce the guard the retired page-type and daily-requests reports hardcoded.",
  "source": "GOOGLE_BIG_QUERY",
  "sourceInfo": {
    "appKey": "GCP_BQ_KAM_CREDENTIALS"
  },
  "cacheInfo": {
    "isCachingEnabled": true,
    "cachingExpiryInSec": 900
  },
  "attributes": {
    "ad_unit_name": {
      "key": "ad_unit_name",
      "selector": "auf.ad_unit_name",
      "type": "STRING",
      "externalColumnName": "ad_unit_name",
      "description": "Name of the display ad unit (placement slot) the ads served in.",
      "filterTags": [
        "report_group:bu",
        "report_group:rr"
      ]
    },
    "page_type": {
      "key": "page_type",
      "selector": "auf.page_type",
      "type": "STRING",
      "externalColumnName": "page_type",
      "description": "The surface the ad unit served on (SEARCH, CATEGORY, PRODUCT, HOME, ...).",
      "filterTags": [
        "report_group:bu",
        "report_group:rr"
      ]
    },
    "date": {
      "selector": "auf.date",
      "type": "DATE",
      "description": "Calendar date of the Display ad-unit facts row. Group by this for the daily request / response trend.",
      "key": "date",
      "externalColumnName": "date",
      "filterTags": [
        "report_group:bu",
        "report_group:rr"
      ]
    }
  },
  "metrics": {
    "requests": {
      "key": "requests",
      "selector": "COALESCE(SUM(CASE WHEN auf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN auf.requests ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "requests",
      "description": "Ad requests received on this ad unit.",
      "filterTags": [
        "report_group:bu",
        "report_group:rr"
      ]
    },
    "responses": {
      "key": "responses",
      "selector": "COALESCE(SUM(CASE WHEN auf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN auf.non_zero_responses ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "responses",
      "description": "Requests that returned at least one ad (non-zero responses).",
      "filterTags": [
        "report_group:bu",
        "report_group:rr"
      ]
    },
    "response_rate": {
      "selector": "ROUND(SAFE_DIVIDE(SUM(CASE WHEN auf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN auf.non_zero_responses ELSE 0 END) * 100, NULLIF(SUM(CASE WHEN auf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN auf.requests ELSE 0 END), 0)), 2)",
      "type": "FLOAT",
      "description": "Non-zero responses as a percentage of requests for this grouping.",
      "key": "response_rate",
      "externalColumnName": "response_rate",
      "filterTags": [
        "report_group:bu",
        "report_group:rr"
      ]
    },
    "impressions": {
      "key": "impressions",
      "selector": "COALESCE(SUM(CASE WHEN auf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN auf.impressions ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "impressions",
      "description": "Ad impressions served on this ad unit.",
      "filterTags": [
        "report_group:bu",
        "report_group:rr"
      ]
    },
    "clicks": {
      "key": "clicks",
      "selector": "COALESCE(SUM(CASE WHEN auf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN auf.clicks ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "clicks",
      "description": "Ad clicks on this ad unit.",
      "filterTags": [
        "report_group:bu",
        "report_group:rr"
      ]
    },
    "spend": {
      "key": "spend",
      "selector": "COALESCE(SUM(CASE WHEN auf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN auf.cost * scc.conversion_factor ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "spend",
      "description": "Ad spend on this ad unit, converted to the marketplace currency.",
      "filterTags": [
        "report_group:bu",
        "report_group:rr"
      ]
    },
    "revenue": {
      "key": "revenue",
      "selector": "COALESCE(SUM(CASE WHEN auf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN auf.program_per_click_timestamp_sales * scc.conversion_factor ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "revenue",
      "description": "Attributed sales (per-click-timestamp) for this ad unit, converted to the marketplace currency. Python divides by spend for ROI.",
      "filterTags": [
        "report_group:bu",
        "report_group:rr"
      ]
    },
    "view_product": {
      "key": "view_product",
      "selector": "COALESCE(SUM(CASE WHEN auf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN auf.program_per_click_timestamp_viewproduct ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "view_product",
      "description": "View-product funnel events (per-click-timestamp) attributed to this ad unit.",
      "filterTags": [
        "report_group:bu",
        "report_group:rr"
      ]
    },
    "add_to_cart": {
      "key": "add_to_cart",
      "selector": "COALESCE(SUM(CASE WHEN auf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN auf.program_per_click_timestamp_add_to_cart ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "add_to_cart",
      "description": "Add-to-cart funnel events (per-click-timestamp) attributed to this ad unit.",
      "filterTags": [
        "report_group:bu",
        "report_group:rr"
      ]
    },
    "conversions": {
      "key": "conversions",
      "selector": "COALESCE(SUM(CASE WHEN auf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN auf.program_per_click_timestamp_conversions ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "conversions",
      "description": "Conversion funnel events (per-click-timestamp) attributed to this ad unit.",
      "filterTags": [
        "report_group:bu",
        "report_group:rr"
      ]
    }
  },
  "dateRanges": {
    "count": 1,
    "dataAvailabilityDays": 90,
    "maxDataFetchDaysDuration": 31
  },
  "query": {
    "REPORTING": "SELECT __ATTRIBUTES__, __METRICS__ FROM `prj-onlinesales-prod-01.reporting.os_display_ads_ad_unit_facts` AS auf INNER JOIN `prj-onlinesales-prod-01.reporting.marketplace_clients` AS mc ON auf.marketplace_client_id = mc.marketplace_client_id LEFT JOIN `prj-onlinesales-prod-01.reporting.static_currency_conversion` AS scc ON scc.from_currency = 'USD' AND scc.to_currency = mc.currency WHERE mc.agency_id = '__AGENCY_ID__' AND auf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' AND __FILTER__ GROUP BY __ATTRIBUTES_GROUP_BY__;",
    "MERCHANT": "",
    "GROUPED": ""
  },
  "application": "irisTestApplication"
}

{
  "reportType": "INTERNAL_PERF_CAMPAIGN_INVENTORY",
  "externalReportType": "CAMPAIGN_INVENTORY_REPORT",
  "visibility": "INTERNAL_PERFORMANCE",
  "filterTags": [
    "report_group:bu"
  ],
  "externalRequiredFilters": [],
  "description": "Inventory / ad-unit slots selected by Display campaigns for a marketplace over a period, one row per ad-unit (inventory) slot x campaign group: spend, impressions, clicks, CTR, CPM, program GMV (ad-attributed sales) and ROAS. Source is os_brand_ads_network_level_facts (Display brand ads). Filter by os_client_id (advertiser client) and/or campaign_group_id to scope to specific Display campaigns.",
  "source": "GOOGLE_BIG_QUERY",
  "sourceInfo": {
    "appKey": "GCP_BQ_KAM_CREDENTIALS"
  },
  "cacheInfo": {
    "isCachingEnabled": true,
    "cachingExpiryInSec": 900
  },
  "attributes": {
    "inventory_name": {
      "key": "inventory_name",
      "selector": "bad.au_display_name",
      "type": "STRING",
      "externalColumnName": "inventory_name",
      "description": "Display inventory / ad-unit slot display name the campaign served on.",
      "filterTags": [
        "report_group:bu"
      ]
    },
    "campaign_group_name": {
      "key": "campaign_group_name",
      "selector": "mcgd.marketing_campaign_group_alias",
      "type": "STRING",
      "externalColumnName": "campaign_group_name",
      "description": "Human-readable Display campaign group (campaign) name.",
      "filterTags": [
        "report_group:bu"
      ]
    },
    "campaign_group_id": {
      "key": "campaign_group_id",
      "selector": "mcgd.marketing_campaign_group_id",
      "type": "STRING",
      "externalColumnName": "campaign_group_id",
      "description": "Marketing campaign group id of the Display campaign. Use as a filter to scope to specific campaign group(s).",
      "filterTags": [
        "report_group:bu"
      ]
    },
    "os_client_id": {
      "key": "os_client_id",
      "selector": "baf.client_id",
      "type": "STRING",
      "externalColumnName": "os_client_id",
      "description": "OnlineSales client id of the advertiser running the campaign (working id for internal analysis). Use as a filter to scope to specific client(s).",
      "filterTags": [
        "report_group:bu"
      ]
    }
  },
  "metrics": {
    "spend": {
      "key": "spend",
      "selector": "COALESCE(SUM(CASE WHEN baf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN baf.cost ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "spend",
      "description": "Ad spend on this inventory slot for this campaign (fact-table native currency, unconverted per source).",
      "filterTags": [
        "report_group:bu"
      ]
    },
    "impressions": {
      "key": "impressions",
      "selector": "COALESCE(SUM(CASE WHEN baf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN baf.onsite_impressions ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "impressions",
      "description": "Onsite ad impressions on this inventory slot for this campaign.",
      "filterTags": [
        "report_group:bu"
      ]
    },
    "clicks": {
      "key": "clicks",
      "selector": "COALESCE(SUM(CASE WHEN baf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN baf.clicks ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "clicks",
      "description": "Ad clicks on this inventory slot for this campaign.",
      "filterTags": [
        "report_group:bu"
      ]
    },
    "ctr": {
      "key": "ctr",
      "selector": "COALESCE(ROUND(SAFE_DIVIDE(SUM(CASE WHEN baf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN baf.clicks ELSE 0 END) * 100.0, NULLIF(SUM(CASE WHEN baf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN baf.onsite_impressions ELSE 0 END), 0)), 2), 0)",
      "type": "FLOAT",
      "externalColumnName": "ctr",
      "description": "Click-through rate (%) = clicks / impressions * 100 for this inventory slot x campaign.",
      "filterTags": [
        "report_group:bu"
      ]
    },
    "cpm": {
      "key": "cpm",
      "selector": "COALESCE(ROUND(SAFE_DIVIDE(SUM(CASE WHEN baf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN baf.cost ELSE 0 END) * 1000, NULLIF(SUM(CASE WHEN baf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN baf.onsite_impressions ELSE 0 END), 0)), 4), 0)",
      "type": "FLOAT",
      "externalColumnName": "cpm",
      "description": "Cost per mille = spend / impressions * 1000 for this inventory slot x campaign (fact-table native currency).",
      "filterTags": [
        "report_group:bu"
      ]
    },
    "program_gmv": {
      "key": "program_gmv",
      "selector": "COALESCE(SUM(CASE WHEN baf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN baf.program_per_click_timestamp_sales ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "program_gmv",
      "description": "PROGRAM (ad-attributed, per-click-timestamp) GMV / sales on this inventory slot for this campaign (fact-table native currency).",
      "filterTags": [
        "report_group:bu"
      ]
    },
    "roas": {
      "key": "roas",
      "selector": "COALESCE(ROUND(SAFE_DIVIDE(SUM(CASE WHEN baf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN baf.program_per_click_timestamp_sales ELSE 0 END), NULLIF(SUM(CASE WHEN baf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN baf.cost ELSE 0 END), 0)), 4), 0)",
      "type": "FLOAT",
      "externalColumnName": "roas",
      "description": "ROI / ROAS = program_gmv / spend for this inventory slot x campaign.",
      "filterTags": [
        "report_group:bu"
      ]
    }
  },
  "dateRanges": {
    "count": 1,
    "dataAvailabilityDays": 90,
    "maxDataFetchDaysDuration": 31
  },
  "query": {
    "REPORTING": "SELECT __ATTRIBUTES__, __METRICS__ FROM `prj-onlinesales-prod-01.reporting.os_brand_ads_network_level_facts` AS baf JOIN `prj-onlinesales-prod-01.reporting.campaign_tagging_data` AS ctd ON ctd.campaign_id = baf.campaign_id AND ctd.client_id = baf.client_id JOIN `prj-onlinesales-prod-01.reporting.marketing_campaign_group_dimensions` AS mcgd ON mcgd.marketing_campaign_group_id = ctd.marketing_campaign_group_id AND mcgd.client_id = ctd.client_id AND mcgd.campaign_origin != 'PACKAGE_BASED' JOIN `prj-onlinesales-prod-01.reporting.brand_ads_dimensions` AS bad ON bad.campaign_id = ctd.campaign_id AND baf.ad_id = bad.ad_id AND bad.account_id = ctd.account_id AND baf.ad_creative_id = bad.ad_creative_id AND baf.account_id = bad.account_id AND baf.campaign_id = bad.campaign_id AND baf.client_id = bad.client_id AND baf.marketplace_client_id = bad.marketplace_client_id AND baf.inventory_ad_unit_id = bad.inventory_ad_unit_id JOIN `prj-onlinesales-prod-01.reporting.marketplace_clients` AS mc ON baf.marketplace_client_id = mc.marketplace_client_id WHERE mc.agency_id = '__AGENCY_ID__' AND baf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' AND __FILTER__ GROUP BY __ATTRIBUTES_GROUP_BY__;",
    "MERCHANT": "",
    "GROUPED": ""
  },
  "application": "irisTestApplication"
}

{
  "reportType": "INTERNAL_PERF_CATEGORY_QUADRANT",
  "externalReportType": "CATEGORY_QUADRANT_REPORT",
  "visibility": "INTERNAL_PERFORMANCE",
  "filterTags": [
    "report_group:bu",
    "report_group:category"
  ],
  "externalRequiredFilters": [],
  "description": "PLA category-level (L1/L2/L3) quadrant for a marketplace over ONE period, from the daily category quadrant fact: per-category requests, response rate (%), currency-converted spend and daily budget, budget-utilisation (%), plus the distinct campaign and merchant counts active in the category. Grouped by the category hierarchy (category_l1 / category_l2 / category_l3). category_level ('category_l1' | 'category_l2' | 'category_l3') selects the granularity of the quadrant rows and MUST be paired with the matching group-by level: filter category_level='category_l1' and request category_l1; 'category_l2' with category_l1+category_l2; 'category_l3' with all three. Only categories with >5000 requests over the period are returned. Called once per period; run current + baseline to compare.",
  "source": "GOOGLE_BIG_QUERY",
  "sourceInfo": {
    "appKey": "GCP_BQ_KAM_CREDENTIALS"
  },
  "cacheInfo": {
    "isCachingEnabled": true,
    "cachingExpiryInSec": 900
  },
  "attributes": {
    "category_level": {
      "key": "category_level",
      "selector": "q.category_level",
      "type": "STRING",
      "externalColumnName": "category_level",
      "description": "Granularity of the quadrant rows: 'category_l1', 'category_l2' or 'category_l3'. Per-call filter — set it to match the category level you group by (l1 -> group category_l1; l2 -> category_l1+category_l2; l3 -> all three).",
      "filterTags": [
        "report_group:bu",
        "report_group:category"
      ]
    },
    "category_l1": {
      "key": "category_l1",
      "selector": "q.category_l1",
      "type": "STRING",
      "externalColumnName": "category_l1",
      "description": "Top-level (L1) product category the quadrant requests/spend were attributed to.",
      "filterTags": [
        "report_group:bu",
        "report_group:category"
      ]
    },
    "category_l2": {
      "key": "category_l2",
      "selector": "q.category_l2",
      "type": "STRING",
      "externalColumnName": "category_l2",
      "description": "Second-level (L2) product category ('na' at category_l1 granularity).",
      "filterTags": [
        "report_group:bu",
        "report_group:category"
      ]
    },
    "category_l3": {
      "key": "category_l3",
      "selector": "q.category_l3",
      "type": "STRING",
      "externalColumnName": "category_l3",
      "description": "Third-level (L3) product category ('na' at category_l1 / category_l2 granularity).",
      "filterTags": [
        "report_group:bu",
        "report_group:category"
      ]
    }
  },
  "metrics": {
    "requests": {
      "key": "requests",
      "selector": "ROUND(AVG(q.request_count), 2)",
      "type": "FLOAT",
      "externalColumnName": "requests",
      "description": "Ad requests received for this category over the period.",
      "filterTags": [
        "report_group:bu",
        "report_group:category"
      ]
    },
    "response_rate": {
      "key": "response_rate",
      "selector": "CASE WHEN ROUND(AVG(q.response_percentage), 2) > 100 THEN 100 ELSE ROUND(AVG(q.response_percentage), 2) END",
      "type": "FLOAT",
      "externalColumnName": "response_rate",
      "description": "Response rate (%) = non-zero responses / requests * 100 for this category, capped at 100.",
      "filterTags": [
        "report_group:bu",
        "report_group:category"
      ]
    },
    "spend": {
      "key": "spend",
      "selector": "ROUND(AVG(q.cost), 2)",
      "type": "FLOAT",
      "externalColumnName": "spend",
      "description": "Ad spend for this category over the period, converted to the marketplace currency.",
      "filterTags": [
        "report_group:bu",
        "report_group:category"
      ]
    },
    "campaign_group_daily_budget": {
      "key": "campaign_group_daily_budget",
      "selector": "CASE WHEN AVG(q.daily_budget) > AVG(q.cost) THEN ROUND(AVG(q.daily_budget), 2) ELSE ROUND(AVG(q.cost), 2) END",
      "type": "FLOAT",
      "externalColumnName": "campaign_group_daily_budget",
      "description": "Daily budget attributed to this category (converted to marketplace currency), floored to spend when budget < spend.",
      "filterTags": [
        "report_group:bu",
        "report_group:category"
      ]
    },
    "budget_utilisation_perc": {
      "key": "budget_utilisation_perc",
      "selector": "CASE WHEN AVG(q.daily_budget) < AVG(q.cost) OR ROUND(AVG(q.budget_utilisation_perc), 2) > 100 THEN 100 ELSE ROUND(AVG(q.budget_utilisation_perc), 2) END",
      "type": "FLOAT",
      "externalColumnName": "budget_utilisation_perc",
      "description": "Budget utilisation (%) = spend / budget * 100 for this category, capped at 100.",
      "filterTags": [
        "report_group:bu",
        "report_group:category"
      ]
    },
    "uniq_campaigns_count": {
      "key": "uniq_campaigns_count",
      "selector": "COUNT(DISTINCT s.campaign_id)",
      "type": "FLOAT",
      "externalColumnName": "uniq_campaigns_count",
      "description": "Distinct PLA campaigns that had product/spend activity in this category over the period.",
      "filterTags": [
        "report_group:bu",
        "report_group:category"
      ]
    },
    "uniq_merchant_count": {
      "key": "uniq_merchant_count",
      "selector": "COUNT(DISTINCT s.merchant_id)",
      "type": "FLOAT",
      "externalColumnName": "uniq_merchant_count",
      "description": "Distinct merchants that had product/spend activity in this category over the period.",
      "filterTags": [
        "report_group:bu",
        "report_group:category"
      ]
    }
  },
  "dateRanges": {
    "count": 1,
    "dataAvailabilityDays": 90,
    "maxDataFetchDaysDuration": 31
  },
  "query": {
    "REPORTING": "SELECT __ATTRIBUTES__, __METRICS__ FROM (SELECT qd.category_level, qd.category_l1, qd.category_l2, qd.category_l3, SUM(qd.requests) AS request_count, SUM(qd.responses) AS response_count, CASE WHEN SUM(qd.responses) > 0 THEN SUM(qd.responses) * 100.0 / SUM(qd.requests) ELSE 0 END AS response_percentage, SUM(qd.cost_usd * scc.conversion_factor) AS cost, SUM(qd.calculated_budget_usd * scc.conversion_factor) AS daily_budget, CASE WHEN SUM(qd.calculated_budget_usd) > 0 THEN SUM(qd.cost_usd) * 100.0 / SUM(qd.calculated_budget_usd) ELSE 0 END AS budget_utilisation_perc FROM `prj-onlinesales-prod-01.reporting.os_product_ads_daily_category_quadrant_report_pla` AS qd INNER JOIN `prj-onlinesales-prod-01.reporting.agencies` AS a ON a.marketplace_client_id = qd.marketplace_client_id AND a.agency_id = '__AGENCY_ID__' INNER JOIN `prj-onlinesales-prod-01.reporting.static_currency_conversion` AS scc ON scc.from_currency = 'USD' AND scc.to_currency = a.currency WHERE qd.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' AND qd.category_l1 IS NOT NULL AND qd.category_l1 <> 'na' GROUP BY 1, 2, 3, 4 HAVING SUM(qd.requests) > 5000) AS q LEFT JOIN (SELECT CASE WHEN cr.category_l1 IS NULL OR cr.category_l1 = '' THEN 'na' ELSE cr.category_l1 END AS category_l1, CASE WHEN cr.category_l2 IS NULL OR cr.category_l2 = '' THEN 'na' ELSE cr.category_l2 END AS category_l2, CASE WHEN cr.category_l3 IS NULL OR cr.category_l3 = '' THEN 'na' ELSE cr.category_l3 END AS category_l3, cr.merchant_id, cr.marketing_campaign_id AS campaign_id, SUM(cr.cost) AS spend, SUM(cr.product_count) AS product_count FROM `prj-onlinesales-prod-01.reporting.os_product_ads_campaign_category_report_pla` AS cr CROSS JOIN `prj-onlinesales-prod-01.reporting.agencies` AS a2 WHERE a2.marketplace_client_id = cr.marketplace_client_id AND a2.agency_id = '__AGENCY_ID__' AND cr.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' GROUP BY 1, 2, 3, 4, 5 HAVING SUM(cr.product_count) > 0 OR SUM(cr.cost) > 0) AS s ON LOWER(q.category_l1) = LOWER(s.category_l1) AND (q.category_l2 IS NULL OR q.category_l2 = 'na' OR LOWER(q.category_l2) = LOWER(s.category_l2)) AND (q.category_l3 IS NULL OR q.category_l3 = 'na' OR LOWER(q.category_l3) = LOWER(s.category_l3)) WHERE q.category_l1 IS NOT NULL AND __FILTER__ GROUP BY __ATTRIBUTES_GROUP_BY__;",
    "MERCHANT": "",
    "GROUPED": ""
  },
  "application": "irisTestApplication"
}

{
  "reportType": "INTERNAL_PERF_DISPLAY_AD_UNIT",
  "externalReportType": "DISPLAY_AD_UNIT_PERFORMANCE_REPORT",
  "visibility": "INTERNAL_PERFORMANCE",
  "filterTags": [
    "report_group:bu",
    "report_group:rr"
  ],
  "externalRequiredFilters": [],
  "description": "Display ad-unit funnel for a marketplace over a period: requests, non-zero responses, response rate, impressions, clicks, marketplace-currency spend and revenue, and the program funnel events (view-product, add-to-cart, conversions). Group by ad_unit_name and/or page_type for the ad-unit and page-type breakdowns, or by date for the daily request / response trend used in budget-utilisation debugging. Pass a page_type NOT IN ('', 'NA') filter to reproduce the guard the retired page-type and daily-requests reports hardcoded.",
  "source": "GOOGLE_BIG_QUERY",
  "sourceInfo": {
    "appKey": "GCP_BQ_KAM_CREDENTIALS"
  },
  "cacheInfo": {
    "isCachingEnabled": true,
    "cachingExpiryInSec": 900
  },
  "attributes": {
    "ad_unit_name": {
      "key": "ad_unit_name",
      "selector": "auf.ad_unit_name",
      "type": "STRING",
      "externalColumnName": "ad_unit_name",
      "description": "Name of the display ad unit (placement slot) the ads served in.",
      "filterTags": [
        "report_group:bu",
        "report_group:rr"
      ]
    },
    "page_type": {
      "key": "page_type",
      "selector": "auf.page_type",
      "type": "STRING",
      "externalColumnName": "page_type",
      "description": "The surface the ad unit served on (SEARCH, CATEGORY, PRODUCT, HOME, ...).",
      "filterTags": [
        "report_group:bu",
        "report_group:rr"
      ]
    },
    "date": {
      "selector": "auf.date",
      "type": "DATE",
      "description": "Calendar date of the Display ad-unit facts row. Group by this for the daily request / response trend.",
      "key": "date",
      "externalColumnName": "date",
      "filterTags": [
        "report_group:bu",
        "report_group:rr"
      ]
    }
  },
  "metrics": {
    "requests": {
      "key": "requests",
      "selector": "COALESCE(SUM(CASE WHEN auf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN auf.requests ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "requests",
      "description": "Ad requests received on this ad unit.",
      "filterTags": [
        "report_group:bu",
        "report_group:rr"
      ]
    },
    "responses": {
      "key": "responses",
      "selector": "COALESCE(SUM(CASE WHEN auf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN auf.non_zero_responses ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "responses",
      "description": "Requests that returned at least one ad (non-zero responses).",
      "filterTags": [
        "report_group:bu",
        "report_group:rr"
      ]
    },
    "response_rate": {
      "selector": "ROUND(SAFE_DIVIDE(SUM(CASE WHEN auf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN auf.non_zero_responses ELSE 0 END) * 100, NULLIF(SUM(CASE WHEN auf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN auf.requests ELSE 0 END), 0)), 2)",
      "type": "FLOAT",
      "description": "Non-zero responses as a percentage of requests for this grouping.",
      "key": "response_rate",
      "externalColumnName": "response_rate",
      "filterTags": [
        "report_group:bu",
        "report_group:rr"
      ]
    },
    "impressions": {
      "key": "impressions",
      "selector": "COALESCE(SUM(CASE WHEN auf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN auf.impressions ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "impressions",
      "description": "Ad impressions served on this ad unit.",
      "filterTags": [
        "report_group:bu",
        "report_group:rr"
      ]
    },
    "clicks": {
      "key": "clicks",
      "selector": "COALESCE(SUM(CASE WHEN auf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN auf.clicks ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "clicks",
      "description": "Ad clicks on this ad unit.",
      "filterTags": [
        "report_group:bu",
        "report_group:rr"
      ]
    },
    "spend": {
      "key": "spend",
      "selector": "COALESCE(SUM(CASE WHEN auf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN auf.cost * scc.conversion_factor ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "spend",
      "description": "Ad spend on this ad unit, converted to the marketplace currency.",
      "filterTags": [
        "report_group:bu",
        "report_group:rr"
      ]
    },
    "revenue": {
      "key": "revenue",
      "selector": "COALESCE(SUM(CASE WHEN auf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN auf.program_per_click_timestamp_sales * scc.conversion_factor ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "revenue",
      "description": "Attributed sales (per-click-timestamp) for this ad unit, converted to the marketplace currency. Python divides by spend for ROI.",
      "filterTags": [
        "report_group:bu",
        "report_group:rr"
      ]
    },
    "view_product": {
      "key": "view_product",
      "selector": "COALESCE(SUM(CASE WHEN auf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN auf.program_per_click_timestamp_viewproduct ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "view_product",
      "description": "View-product funnel events (per-click-timestamp) attributed to this ad unit.",
      "filterTags": [
        "report_group:bu",
        "report_group:rr"
      ]
    },
    "add_to_cart": {
      "key": "add_to_cart",
      "selector": "COALESCE(SUM(CASE WHEN auf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN auf.program_per_click_timestamp_add_to_cart ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "add_to_cart",
      "description": "Add-to-cart funnel events (per-click-timestamp) attributed to this ad unit.",
      "filterTags": [
        "report_group:bu",
        "report_group:rr"
      ]
    },
    "conversions": {
      "key": "conversions",
      "selector": "COALESCE(SUM(CASE WHEN auf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN auf.program_per_click_timestamp_conversions ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "conversions",
      "description": "Conversion funnel events (per-click-timestamp) attributed to this ad unit.",
      "filterTags": [
        "report_group:bu",
        "report_group:rr"
      ]
    }
  },
  "dateRanges": {
    "count": 1,
    "dataAvailabilityDays": 90,
    "maxDataFetchDaysDuration": 31
  },
  "query": {
    "REPORTING": "SELECT __ATTRIBUTES__, __METRICS__ FROM `prj-onlinesales-prod-01.reporting.os_display_ads_ad_unit_facts` AS auf INNER JOIN `prj-onlinesales-prod-01.reporting.marketplace_clients` AS mc ON auf.marketplace_client_id = mc.marketplace_client_id LEFT JOIN `prj-onlinesales-prod-01.reporting.static_currency_conversion` AS scc ON scc.from_currency = 'USD' AND scc.to_currency = mc.currency WHERE mc.agency_id = '__AGENCY_ID__' AND auf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' AND __FILTER__ GROUP BY __ATTRIBUTES_GROUP_BY__;",
    "MERCHANT": "",
    "GROUPED": ""
  },
  "application": "irisTestApplication"
}

{
  "reportType": "INTERNAL_PERF_DISPLAY_INVENTORY_CAMPAIGNS",
  "externalReportType": "DISPLAY_INVENTORY_CAMPAIGNS_REPORT",
  "visibility": "INTERNAL_PERFORMANCE",
  "filterTags": [
    "report_group:bu",
    "report_group:campaign"
  ],
  "externalRequiredFilters": [
    "ad_unit"
  ],
  "description": "Campaigns running under a specific Display inventory slot for one period. Filter by ad_unit (required) and optionally page_type; returns per campaign-group rows: merchant id/name, os_client_id, campaign-group id/name/type/status/subtype, start/end date, bidding-strategy type, merchant remaining balance, daily budget, spend (raw cost, NOT currency-converted) and CPM. Only rows with cost > 0 that are either BLOCK_BUY or ACTIVE inventory configurations.",
  "source": "GOOGLE_BIG_QUERY",
  "sourceInfo": {
    "appKey": "GCP_BQ_KAM_CREDENTIALS"
  },
  "cacheInfo": {
    "isCachingEnabled": true,
    "cachingExpiryInSec": 900
  },
  "attributes": {
    "merchant_id": {
      "key": "merchant_id",
      "selector": "mmd.merchant_id",
      "type": "STRING",
      "externalColumnName": "merchant_id",
      "description": "Merchant (seller) id owning the campaign group.",
      "filterTags": [
        "report_group:bu",
        "report_group:campaign"
      ]
    },
    "merchant_name": {
      "key": "merchant_name",
      "selector": "mmd.merchant_name",
      "type": "STRING",
      "externalColumnName": "merchant_name",
      "description": "Merchant (seller) display name.",
      "filterTags": [
        "report_group:bu",
        "report_group:campaign"
      ]
    },
    "campaign_group_id": {
      "key": "campaign_group_id",
      "selector": "mcd.marketing_campaign_group_id",
      "type": "STRING",
      "externalColumnName": "campaign_group_id",
      "description": "Marketing campaign-group id.",
      "filterTags": [
        "report_group:bu",
        "report_group:campaign"
      ]
    },
    "campaign_group_name": {
      "key": "campaign_group_name",
      "selector": "mcd.marketing_campaign_group_alias",
      "type": "STRING",
      "externalColumnName": "campaign_group_name",
      "description": "Marketing campaign-group alias / display name.",
      "filterTags": [
        "report_group:bu",
        "report_group:campaign"
      ]
    },
    "os_client_id": {
      "key": "os_client_id",
      "selector": "mmd.client_id",
      "type": "STRING",
      "externalColumnName": "os_client_id",
      "description": "OnlineSales advertiser client id for the merchant.",
      "filterTags": [
        "report_group:bu",
        "report_group:campaign"
      ]
    },
    "campaign_group_type": {
      "key": "campaign_group_type",
      "selector": "CASE WHEN (JSON_EXTRACT_SCALAR(mcgd.metadata, '$.isEanEnabled') = 'true' AND ctd.vendor IN ('google', 'facebook', 'tiktok')) THEN 'Offsite Ad' WHEN mcgd.campaign_type = 'PERFORMANCE' THEN 'Sponsored Product Ad' WHEN mcgd.campaign_type IN ('AWARENESS', 'INVENTORY') THEN 'Sponsored Display Ad' WHEN mcgd.campaign_type IN ('OFFSITE') THEN 'Offsite Ad' ELSE 'Sponsored Offsite Ad' END",
      "type": "STRING",
      "externalColumnName": "campaign_group_type",
      "description": "Derived product family of the campaign group (Sponsored Product Ad / Sponsored Display Ad / Offsite Ad / Sponsored Offsite Ad).",
      "filterTags": [
        "report_group:bu",
        "report_group:campaign"
      ]
    },
    "campaign_group_status": {
      "key": "campaign_group_status",
      "selector": "REPLACE(mcgd.effective_status, '_', ' ')",
      "type": "STRING",
      "externalColumnName": "campaign_group_status",
      "description": "Effective status of the campaign group with underscores replaced by spaces.",
      "filterTags": [
        "report_group:bu",
        "report_group:campaign"
      ]
    },
    "campaign_group_start_date": {
      "key": "campaign_group_start_date",
      "selector": "CAST(DATE(TIMESTAMP(mcgd.start_date, 'UTC'), mc.timezone) AS STRING)",
      "type": "STRING",
      "externalColumnName": "campaign_group_start_date",
      "description": "Campaign-group start date in the marketplace timezone (from marketplace_clients.timezone).",
      "filterTags": [
        "report_group:bu",
        "report_group:campaign"
      ]
    },
    "campaign_group_end_date": {
      "key": "campaign_group_end_date",
      "selector": "CASE WHEN DATETIME(TIMESTAMP(mcgd.end_date, 'UTC'), mc.timezone) >= '2036-01-01' THEN NULL ELSE CAST(DATE(TIMESTAMP(mcgd.end_date, 'UTC'), mc.timezone) AS STRING) END",
      "type": "STRING",
      "externalColumnName": "campaign_group_end_date",
      "description": "Campaign-group end date in the marketplace timezone; NULL for effectively open-ended (>= 2036-01-01).",
      "filterTags": [
        "report_group:bu",
        "report_group:campaign"
      ]
    },
    "campaign_group_subtype": {
      "key": "campaign_group_subtype",
      "selector": "CASE WHEN (JSON_EXTRACT_SCALAR(mcgd.metadata, '$.isEanEnabled') = 'true' AND ctd.vendor IN ('google', 'facebook', 'tiktok')) THEN 'Manual' WHEN mcgd.campaign_type = 'PERFORMANCE' AND mcgd.campaign_subtype = 'SMART_SHOPPING' AND ((mcgd.bidding_strategy IN ('AUTO_CPC', 'AUTO_CPM') AND mcgd.objective_name IN ('Visitors', 'Visibility')) OR mcgd.objective_name = 'Absolute Revenue') THEN 'Smart Shopping' WHEN mcgd.campaign_type = 'PERFORMANCE' AND mcgd.objective_name IN ('Visitors', 'Visibility') AND mcgd.bidding_strategy IN ('CPC', 'CPM') THEN 'Manual' WHEN mcgd.campaign_type = 'PERFORMANCE' AND mcgd.campaign_subtype = 'OS_ADS_SEARCH' THEN 'Search-Only' WHEN mcgd.campaign_type IN ('AWARENESS', 'INVENTORY') AND mcgd.campaign_subtype = 'AUCTION' THEN 'Auction' WHEN mcgd.campaign_type IN ('AWARENESS', 'INVENTORY') AND mcgd.campaign_subtype = 'BLOCK_BUY' THEN 'Guaranteed' WHEN mcgd.campaign_type IN ('AWARENESS', 'INVENTORY') AND mcgd.campaign_subtype = 'PRE_AUCTION' THEN 'Auction Packages' WHEN mcgd.campaign_type IN ('OFFSITE') AND mcgd.campaign_subtype IN ('FACEBOOK_PRODUCT_AD', 'FACEBOOK', 'FACEBOOK_CAROUSEL_AD') THEN 'Facebook' WHEN mcgd.campaign_type IN ('OFFSITE') AND mcgd.campaign_subtype IN ('FACEBOOK_DPA') THEN 'Facebook DPA' WHEN mcgd.campaign_type IN ('OFFSITE') AND mcgd.campaign_subtype IN ('GOOGLE_PERFORMANCE_MAX_SHOPPING', 'GOOGLE_PERFORMANCE_MAX') THEN 'Google Performance Max' WHEN mcgd.campaign_type IN ('OFFSITE') AND mcgd.campaign_subtype IN ('GOOGLE_PRODUCT_AD', 'GOOGLE_SEARCH_TEXT_AD') THEN 'Google' WHEN mcgd.campaign_type IN ('OFFSITE') AND mcgd.campaign_subtype IN ('TIKTOK_TRAFFIC') THEN 'Tiktok Traffic' WHEN mcgd.campaign_type IN ('OFFSITE') AND mcgd.campaign_subtype IN ('TIKTOK_REACH') THEN 'Tiktok Reach' END",
      "type": "STRING",
      "externalColumnName": "campaign_group_subtype",
      "description": "Derived campaign-group subtype label (Smart Shopping / Manual / Search-Only / Auction / Guaranteed / Auction Packages / Facebook / Google / Tiktok variants).",
      "filterTags": [
        "report_group:bu",
        "report_group:campaign"
      ]
    },
    "merchant_remaining_balance": {
      "key": "merchant_remaining_balance",
      "selector": "ROUND(CASE WHEN ROUND(mmd.remaning_balance, 0) <= 0.01 THEN 0 ELSE ROUND(mmd.remaning_balance, 0) END, 2)",
      "type": "FLOAT",
      "externalColumnName": "merchant_remaining_balance",
      "description": "Merchant remaining wallet balance (floored to 0 when <= 0.01).",
      "filterTags": [
        "report_group:bu",
        "report_group:campaign"
      ]
    },
    "campaign_group_daily_budget": {
      "key": "campaign_group_daily_budget",
      "selector": "mcgd.daily_budget",
      "type": "FLOAT",
      "externalColumnName": "campaign_group_daily_budget",
      "description": "Current daily budget configured on the campaign group.",
      "filterTags": [
        "report_group:bu",
        "report_group:campaign"
      ]
    },
    "campaign_group_bidding_strategy_type": {
      "key": "campaign_group_bidding_strategy_type",
      "selector": "CASE WHEN (mcd.campaign_type = 'PERFORMANCE' AND mcd.objective_name IN ('Visitors', 'Visibility') AND mcd.bidding_strategy = 'AUTO_CPC') THEN 'Max Performance CPC' WHEN (mcd.campaign_type = 'PERFORMANCE' AND mcd.objective_name IN ('Visitors', 'Visibility') AND mcd.bidding_strategy = 'AUTO_CPM') THEN 'Max Performance CPM' WHEN (mcd.campaign_type = 'PERFORMANCE' AND mcd.objective_name IN ('Visitors', 'Visibility') AND mcd.bidding_strategy IN ('CPM', 'CPC')) THEN mcd.bidding_strategy WHEN mcd.campaign_type IN ('INVENTORY', 'AWARENESS') AND mcd.campaign_subtype = 'PRE_AUCTION' THEN 'NA' WHEN mcd.objective_name IN ('Absolute Revenue') THEN 'ROI' WHEN mcd.objective_name IN ('Visibility', 'Reach') AND mcd.campaign_subtype = 'AUCTION' THEN UPPER(JSON_EXTRACT_SCALAR(mcd.campaign_setting_metadata, '$.bidding_strategy_type')) WHEN mcd.objective_name IN ('Visibility', 'Reach') AND mcd.campaign_subtype = 'BLOCK_BUY' AND JSON_EXTRACT_SCALAR(mcd.campaign_setting_metadata, '$.bidding_strategy_type') = 'CPM' THEN 'Fixed CPM' WHEN mcd.objective_name IN ('Visibility', 'Reach') AND mcd.campaign_subtype = 'BLOCK_BUY' AND JSON_EXTRACT_SCALAR(mcd.campaign_setting_metadata, '$.bidding_strategy_type') = 'CPD' THEN 'CPD' ELSE 'UNKNOWN' END",
      "type": "STRING",
      "externalColumnName": "campaign_group_bidding_strategy_type",
      "description": "Derived bidding-strategy label for the campaign group.",
      "filterTags": [
        "report_group:bu",
        "report_group:campaign"
      ]
    },
    "ad_unit": {
      "key": "ad_unit",
      "selector": "rpt.ad_unit_name",
      "type": "STRING",
      "externalColumnName": "ad_unit",
      "description": "Display inventory ad-unit / slot name. REQUIRED per-call filter (case-sensitive equality on ad_unit_name).",
      "filterTags": [
        "report_group:bu",
        "report_group:campaign"
      ]
    },
    "page_type": {
      "key": "page_type",
      "selector": "rpt.page_type",
      "type": "STRING",
      "externalColumnName": "page_type",
      "description": "Page type the inventory slot served on (SEARCH / CATEGORY / PRODUCT / HOME / ...). Optional per-call filter.",
      "filterTags": [
        "report_group:bu",
        "report_group:campaign"
      ]
    }
  },
  "metrics": {
    "spend": {
      "key": "spend",
      "selector": "COALESCE(ROUND(SUM(CASE WHEN rpt.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN rpt.cost ELSE 0 END), 2), 0)",
      "type": "FLOAT",
      "externalColumnName": "spend",
      "description": "Inventory spend under this ad-unit slot (raw cost, NOT currency-converted; matches the source query).",
      "filterTags": [
        "report_group:bu",
        "report_group:campaign"
      ]
    },
    "cpm": {
      "key": "cpm",
      "selector": "ROUND(CASE WHEN SUM(CASE WHEN rpt.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN rpt.impressions ELSE 0 END) > 0 THEN SUM(CASE WHEN rpt.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN rpt.cost ELSE 0 END) * 1000 / SUM(CASE WHEN rpt.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN rpt.impressions ELSE 0 END) ELSE 0 END, 2)",
      "type": "FLOAT",
      "externalColumnName": "cpm",
      "description": "Cost per mille = spend * 1000 / impressions under this ad-unit slot (0 when no impressions).",
      "filterTags": [
        "report_group:bu",
        "report_group:campaign"
      ]
    }
  },
  "dateRanges": {
    "count": 1,
    "dataAvailabilityDays": 90,
    "maxDataFetchDaysDuration": 31
  },
  "query": {
    "REPORTING": "SELECT __ATTRIBUTES__, __METRICS__ FROM `prj-onlinesales-prod-01.reporting.os_display_ads_ad_targeting_report` AS rpt INNER JOIN `prj-onlinesales-prod-01.reporting.agencies` AS ag ON ag.marketplace_client_id = rpt.marketplace_client_id AND ag.agency_id = '__AGENCY_ID__' INNER JOIN `prj-onlinesales-prod-01.reporting.monetize_merchant_dimensions` AS mmd ON mmd.marketplace_client_id = rpt.marketplace_client_id AND mmd.merchant_id = rpt.merchant_id AND mmd.agency_id = '__AGENCY_ID__' INNER JOIN `prj-onlinesales-prod-01.reporting.campaign_tagging_data` AS ctd ON ctd.client_id = rpt.client_id AND ctd.campaign_id = rpt.campaign_id INNER JOIN `prj-onlinesales-prod-01.reporting.marketing_campaign_group_dimensions` AS mcgd ON mcgd.marketing_campaign_group_id = ctd.marketing_campaign_group_id AND mcgd.client_id = ctd.client_id INNER JOIN `prj-onlinesales-prod-01.reporting.marketing_campaign_dimensions` AS mcd ON mcd.client_id = ctd.client_id AND mcd.marketing_campaign_id = ctd.marketing_campaign_id INNER JOIN `prj-onlinesales-prod-01.reporting.marketplace_clients` AS mc ON mc.marketplace_client_id = rpt.marketplace_client_id AND mc.agency_id = ag.agency_id AND mc.agency_id = mmd.agency_id LEFT JOIN `prj-onlinesales-prod-01.reporting.os_ads_db_campaign_inventory_configurations` AS oci ON SAFE_CAST(oci.marketplace_client_id AS STRING) = rpt.marketplace_client_id AND SAFE_CAST(oci.client_id AS STRING) = rpt.client_id AND SAFE_CAST(oci.campaign_id AS STRING) = rpt.campaign_id INNER JOIN `prj-onlinesales-prod-01.reporting.os_ads_db_status_types` AS st ON oci.status_type_id = st.id WHERE rpt.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' AND rpt.cost > 0 AND (mcgd.campaign_subtype = 'BLOCK_BUY' OR st.name = 'ACTIVE') AND __FILTER__ GROUP BY __ATTRIBUTES_GROUP_BY__;",
    "MERCHANT": "",
    "GROUPED": ""
  },
  "application": "irisTestApplication"
}

{
  "reportType": "INTERNAL_PERF_DISPLAY_QUADRANT",
  "externalReportType": "DISPLAY_QUADRANT_REPORT",
  "visibility": "INTERNAL_PERFORMANCE",
  "filterTags": [
    "report_group:bu"
  ],
  "externalRequiredFilters": [],
  "description": "Display inventory-level quadrant for a marketplace over ONE period, from the daily display quadrant fact: per inventory (page_type + ad_unit) average request count, response rate (%), impression/response ratio (%), currency-converted spend, budget-utilisation (%), and the distinct active campaign and merchant counts serving that inventory. Grouped by page_type + ad_unit. page_type is an optional per-call filter. Only inventories with >1000 requests over the period are returned. Called once per period; run current + baseline to compare.",
  "source": "GOOGLE_BIG_QUERY",
  "sourceInfo": {
    "appKey": "GCP_BQ_KAM_CREDENTIALS"
  },
  "cacheInfo": {
    "isCachingEnabled": true,
    "cachingExpiryInSec": 900
  },
  "attributes": {
    "page_type": {
      "key": "page_type",
      "selector": "q.page_type",
      "type": "STRING",
      "externalColumnName": "page_type",
      "description": "The surface the display ad served on (SEARCH, CATEGORY, PRODUCT, HOME, ...). Optional per-call filter to scope to one page type.",
      "filterTags": [
        "report_group:bu"
      ]
    },
    "ad_unit": {
      "key": "ad_unit",
      "selector": "q.ad_unit_name",
      "type": "STRING",
      "externalColumnName": "ad_unit",
      "description": "The display ad unit / inventory slot name within the page type.",
      "filterTags": [
        "report_group:bu"
      ]
    }
  },
  "metrics": {
    "requests": {
      "key": "requests",
      "selector": "ROUND(AVG(q.request_count), 2)",
      "type": "FLOAT",
      "externalColumnName": "requests",
      "description": "Average daily ad requests received for this inventory over the period.",
      "filterTags": [
        "report_group:bu"
      ]
    },
    "response_rate": {
      "key": "response_rate",
      "selector": "CASE WHEN ROUND(AVG(q.response_percentage), 2) > 100 THEN 100 ELSE ROUND(AVG(q.response_percentage), 2) END",
      "type": "FLOAT",
      "externalColumnName": "response_rate",
      "description": "Response rate (%) = non-zero responses / requests * 100 for this inventory, capped at 100.",
      "filterTags": [
        "report_group:bu"
      ]
    },
    "impression_responses_ratio": {
      "key": "impression_responses_ratio",
      "selector": "CASE WHEN ROUND(AVG(q.impression_responses_ratio), 2) > 100 THEN 100 ELSE ROUND(AVG(q.impression_responses_ratio), 2) END",
      "type": "FLOAT",
      "externalColumnName": "impression_responses_ratio",
      "description": "Impression/response ratio (%) = impressions / non-zero responses for this inventory, capped at 100 (share of responses that rendered as impressions).",
      "filterTags": [
        "report_group:bu"
      ]
    },
    "spend": {
      "key": "spend",
      "selector": "ROUND(AVG(q.cost), 2)",
      "type": "FLOAT",
      "externalColumnName": "spend",
      "description": "Ad spend for this inventory over the period, converted to the marketplace currency.",
      "filterTags": [
        "report_group:bu"
      ]
    },
    "budget_utilisation_perc": {
      "key": "budget_utilisation_perc",
      "selector": "CASE WHEN AVG(q.daily_budget) < AVG(q.cost) OR ROUND(AVG(q.budget_utilisation_perc), 2) > 100 THEN 100 ELSE ROUND(AVG(q.budget_utilisation_perc), 2) END",
      "type": "FLOAT",
      "externalColumnName": "budget_utilisation_perc",
      "description": "Budget utilisation (%) = spend / budget * 100 for this inventory, capped at 100.",
      "filterTags": [
        "report_group:bu"
      ]
    },
    "uniq_campaigns_count": {
      "key": "uniq_campaigns_count",
      "selector": "COUNT(DISTINCT CASE WHEN s.spend > 0 THEN s.campaign_id END)",
      "type": "FLOAT",
      "externalColumnName": "uniq_campaigns_count",
      "description": "Distinct active display campaigns that had spend on this inventory over the period.",
      "filterTags": [
        "report_group:bu"
      ]
    },
    "uniq_merchant_count": {
      "key": "uniq_merchant_count",
      "selector": "COUNT(DISTINCT CASE WHEN s.spend > 0 THEN s.merchant_id END)",
      "type": "FLOAT",
      "externalColumnName": "uniq_merchant_count",
      "description": "Distinct merchants that had spend on this inventory over the period.",
      "filterTags": [
        "report_group:bu"
      ]
    }
  },
  "dateRanges": {
    "count": 1,
    "dataAvailabilityDays": 90,
    "maxDataFetchDaysDuration": 31
  },
  "query": {
    "REPORTING": "SELECT __ATTRIBUTES__, __METRICS__ FROM (SELECT qd.page_type, qd.ad_unit_name, SUM(qd.requests) AS request_count, SUM(qd.responses) AS response_count, CASE WHEN SUM(qd.requests) > 0 THEN SUM(qd.responses) * 100.0 / SUM(qd.requests) ELSE 0 END AS response_percentage, COALESCE(SAFE_DIVIDE(SUM(qd.impressions), SUM(qd.responses)), 0) AS impression_responses_ratio, SUM(qd.cost_usd * scc.conversion_factor) AS cost, SUM(qd.daily_budget_usd * scc.conversion_factor) AS daily_budget, CASE WHEN SUM(qd.daily_budget_usd) > 0 THEN SUM(qd.cost_usd) * 100.0 / SUM(qd.daily_budget_usd) ELSE 0 END AS budget_utilisation_perc FROM `prj-onlinesales-prod-01.reporting.os_display_ads_daily_quadrant_report` AS qd INNER JOIN `prj-onlinesales-prod-01.reporting.agencies` AS a ON a.marketplace_client_id = qd.marketplace_client_id AND a.agency_id = '__AGENCY_ID__' INNER JOIN `prj-onlinesales-prod-01.reporting.static_currency_conversion` AS scc ON scc.from_currency = 'USD' AND scc.to_currency = a.currency WHERE qd.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' AND qd.page_type IS NOT NULL GROUP BY 1, 2 HAVING SUM(qd.requests) > 1000) AS q LEFT JOIN (SELECT tr.page_type, tr.ad_unit_name, tr.merchant_id, tr.campaign_id, SUM(tr.cost) AS spend FROM `prj-onlinesales-prod-01.reporting.os_display_ads_ad_targeting_report` AS tr INNER JOIN `prj-onlinesales-prod-01.reporting.agencies` AS a2 ON a2.marketplace_client_id = tr.marketplace_client_id AND a2.agency_id = '__AGENCY_ID__' INNER JOIN `prj-onlinesales-prod-01.reporting.os_ads_db_campaigns` AS c ON tr.campaign_id = SAFE_CAST(c.id AS STRING) AND tr.client_id = SAFE_CAST(c.client_id AS STRING) INNER JOIN `prj-onlinesales-prod-01.reporting.os_ads_db_campaign_types` AS ct ON c.campaign_type_id = ct.id LEFT JOIN `prj-onlinesales-prod-01.reporting.os_ads_db_campaign_inventory_configurations` AS cic ON SAFE_CAST(cic.marketplace_client_id AS STRING) = a2.marketplace_client_id AND SAFE_CAST(cic.marketplace_client_id AS STRING) = tr.marketplace_client_id AND SAFE_CAST(cic.client_id AS STRING) = tr.client_id AND SAFE_CAST(cic.campaign_id AS STRING) = tr.campaign_id AND cic.campaign_id = c.id INNER JOIN `prj-onlinesales-prod-01.reporting.os_ads_db_status_types` AS st ON cic.status_type_id = st.id WHERE tr.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' AND (ct.name = 'BLOCK_BUY' OR st.name = 'ACTIVE') GROUP BY 1, 2, 3, 4) AS s ON LOWER(q.page_type) = LOWER(s.page_type) AND LOWER(q.ad_unit_name) = LOWER(s.ad_unit_name) WHERE q.page_type IS NOT NULL AND __FILTER__ GROUP BY __ATTRIBUTES_GROUP_BY__;",
    "MERCHANT": "",
    "GROUPED": ""
  },
  "application": "irisTestApplication"
}

{
  "reportType": "INTERNAL_PERF_WALLET_BALANCE",
  "externalReportType": "WALLET_BALANCE_REPORT",
  "visibility": "INTERNAL_PERFORMANCE",
  "filterTags": [
