  "source": "GOOGLE_BIG_QUERY",
  "sourceInfo": {
    "appKey": "GCP_BQ_KAM_CREDENTIALS"
  },
  "cacheInfo": {
    "isCachingEnabled": true,
    "cachingExpiryInSec": 900
  },
  "attributes": {
    "campaign_id": {
      "key": "campaign_id",
      "selector": "ctd.marketing_campaign_id",
      "type": "STRING",
      "externalColumnName": "campaign_id",
      "description": "The marketing campaign id (campaign_tagging_data.marketing_campaign_id) resolved from the internal click campaign_id. MANDATORY per-call filter used to scope the report to specific campaign(s).",
      "filterTags": [
        "report_group:budget_pacing"
      ]
    },
    "page_type": {
      "key": "page_type",
      "selector": "c.page_type",
      "type": "STRING",
      "externalColumnName": "page_type",
      "description": "The surface the click occurred on (raw page_type, e.g. SEARCH / CATEGORY / PRODUCT / HOME). The Python layer collapses this into SEARCH vs NON-SEARCH.",
      "filterTags": [
        "report_group:budget_pacing"
      ]
    },
    "minute_timestamp": {
      "key": "minute_timestamp",
      "selector": "SAFE_CAST(DATETIME_TRUNC(CAST(DATETIME(TIMESTAMP(c.response_timestamp_utc), '__SP_TIMEZONE__') AS DATETIME), MINUTE) AS STRING)",
      "type": "STRING",
      "externalColumnName": "minute_timestamp",
      "description": "Local (marketplace timezone) timestamp truncated to the minute for this click bucket, derived from response_timestamp_utc via __SP_TIMEZONE__.",
      "filterTags": [
        "report_group:budget_pacing"
      ]
    },
    "hour": {
      "key": "hour",
      "selector": "SAFE_CAST(EXTRACT(HOUR FROM CAST(DATETIME(TIMESTAMP(c.response_timestamp_utc), '__SP_TIMEZONE__') AS DATETIME)) AS STRING)",
      "type": "STRING",
      "externalColumnName": "hour",
      "description": "Local hour of day (0-23, marketplace timezone) the clicks/spend fell in, from response_timestamp_utc via __SP_TIMEZONE__.",
      "filterTags": [
        "report_group:budget_pacing"
      ]
    },
    "minute": {
      "key": "minute",
      "selector": "SAFE_CAST(EXTRACT(MINUTE FROM CAST(DATETIME(TIMESTAMP(c.response_timestamp_utc), '__SP_TIMEZONE__') AS DATETIME)) AS STRING)",
      "type": "STRING",
      "externalColumnName": "minute",
      "description": "Local minute within the hour (0-59, marketplace timezone) the clicks/spend fell in, from response_timestamp_utc via __SP_TIMEZONE__.",
      "filterTags": [
        "report_group:budget_pacing"
      ]
    }
  },
  "metrics": {
    "clicks": {
      "key": "clicks",
      "selector": "COALESCE(SUM(CASE WHEN DATE(TIMESTAMP(c.response_timestamp_utc), '__SP_TIMEZONE__') BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN c.unique_click ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "clicks",
      "description": "Valid unique clicks in this local minute for this campaign + page_type.",
      "filterTags": [
        "report_group:budget_pacing"
      ]
    },
    "spend": {
      "key": "spend",
      "selector": "COALESCE(SUM(CASE WHEN DATE(TIMESTAMP(c.response_timestamp_utc), '__SP_TIMEZONE__') BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN COALESCE(c.bid, 0) * scc.conversion_factor ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "spend",
      "description": "Click spend in this local minute (click bid) converted from USD to the marketplace currency.",
      "filterTags": [
        "report_group:budget_pacing"
      ]
    }
  },
  "dateRanges": {
    "count": 1,
    "dataAvailabilityDays": 90,
    "maxDataFetchDaysDuration": 31
  },
  "query": {
    "REPORTING": "SELECT __ATTRIBUTES__, __METRICS__ FROM `prj-onlinesales-prod-01.reporting.os_product_ads_response_to_clicks_mapping` AS c JOIN `prj-onlinesales-prod-01.reporting.marketplace_clients` AS mc ON c.marketplace_client_id = mc.marketplace_client_id LEFT JOIN `prj-onlinesales-prod-01.reporting.static_currency_conversion` AS scc ON scc.from_currency = 'USD' AND scc.to_currency = mc.currency JOIN `prj-onlinesales-prod-01.reporting.campaign_tagging_data` AS ctd ON SAFE_CAST(c.campaign_id AS STRING) = ctd.campaign_id WHERE mc.agency_id = '__AGENCY_ID__' AND c.is_valid_click = TRUE AND DATE(TIMESTAMP(c.response_timestamp_utc), '__SP_TIMEZONE__') BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' AND __FILTER__ GROUP BY __ATTRIBUTES_GROUP_BY__;",
    "MERCHANT": "",
    "GROUPED": ""
  },
  "application": "irisTestApplication"
}

