    "minute": {
      "key": "minute",
      "selector": "EXTRACT(MINUTE FROM CAST(DATETIME(TIMESTAMP(i.response_timestamp_utc), '__SP_TIMEZONE__') AS DATETIME))",
      "type": "FLOAT",
      "externalColumnName": "minute",
      "description": "Minute-of-hour (0-59) in the marketplace's local timezone; combine with hour for per-minute granularity.",
      "filterTags": [
        "report_group:budget_pacing"
      ]
    }
  },
  "metrics": {
    "impressions": {
      "key": "impressions",
      "selector": "COALESCE(SUM(CASE WHEN DATE(TIMESTAMP(i.response_timestamp_utc), '__SP_TIMEZONE__') BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN i.unique_impressions ELSE 0 END), 0)",
