      ]
    },
    "spend": {
      "key": "spend",
      "selector": "COALESCE(SUM(CASE WHEN DATE(TIMESTAMP(i.response_timestamp_utc), '__SP_TIMEZONE__') BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN COALESCE(i.bid, 0) * scc.conversion_factor ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "spend",
      "description": "Spend in this minute (bid), converted from USD to the marketplace currency via static_currency_conversion.",
      "filterTags": [
        "report_group:budget_pacing"
      ]
    }
  },
  "dateRanges": {
    "count": 1,
    "dataAvailabilityDays": 90,
    "maxDataFetchDaysDuration": 31
  },
  "query": {
    "REPORTING": "SELECT __ATTRIBUTES__, __METRICS__ FROM `prj-onlinesales-prod-01.reporting.os_product_ads_response_to_impressions_mapping` AS i INNER JOIN `prj-onlinesales-prod-01.reporting.campaign_tagging_data` AS t ON i.campaign_id = t.campaign_id JOIN `prj-onlinesales-prod-01.reporting.marketplace_clients` AS mc ON i.marketplace_client_id = mc.marketplace_client_id LEFT JOIN `prj-onlinesales-prod-01.reporting.static_currency_conversion` AS scc ON scc.from_currency = 'USD' AND scc.to_currency = mc.currency WHERE mc.agency_id = '__AGENCY_ID__' AND DATE(TIMESTAMP(i.response_timestamp_utc), '__SP_TIMEZONE__') BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' AND __FILTER__ GROUP BY __ATTRIBUTES_GROUP_BY__;",
    "MERCHANT": "",
    "GROUPED": ""
  },
  "application": "irisTestApplication"
}

{
  "reportType": "INTERNAL_PERF_CAMPAIGN_SUBTYPE_CPC",
  "externalReportType": "CAMPAIGN_SUBTYPE_CPC_REPORT",
  "visibility": "INTERNAL_PERFORMANCE",
  "filterTags": [
    "report_group:cpc"
  ],
  "externalRequiredFilters": [],
  "description": "Marketplace-level PLA campaign-subtype buckets (os_ads_search vs smart_shopping vs ...) for a single period, grouped by campaign_subtype: distinct campaign count, spend, clicks, impressions, program GMV, program orders, and CPC per subtype. Restricted to performance-type campaign groups with a non-null subtype.",
  "source": "GOOGLE_BIG_QUERY",
  "sourceInfo": {
    "appKey": "GCP_BQ_KAM_CREDENTIALS"
  },
  "cacheInfo": {
    "isCachingEnabled": true,
    "cachingExpiryInSec": 900
  },
  "attributes": {
    "campaign_subtype": {
      "key": "campaign_subtype",
      "selector": "LOWER(g.campaign_subtype)",
      "type": "STRING",
      "externalColumnName": "campaign_subtype",
      "description": "PLA campaign-subtype bucket the campaign group belongs to (e.g. os_ads_search, smart_shopping), lower-cased. Derived from marketing_campaign_group_dimensions.campaign_subtype.",
      "filterTags": [
        "report_group:cpc"
      ]
    }
  },
  "metrics": {
    "campaign_count": {
      "key": "campaign_count",
      "selector": "COALESCE(COUNT(DISTINCT CASE WHEN cpf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN cpf.campaign_id END), 0)",
      "type": "FLOAT",
      "externalColumnName": "campaign_count",
      "description": "Number of distinct campaigns in this subtype bucket over the period.",
      "filterTags": [
        "report_group:cpc"
      ]
    },
    "spend": {
      "key": "spend",
      "selector": "COALESCE(SUM(CASE WHEN cpf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN cpf.cost ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "spend",
      "description": "Ad spend for this subtype bucket over the period (raw campaign_performance_facts.cost).",
      "filterTags": [
        "report_group:cpc"
      ]
    },
    "clicks": {
      "key": "clicks",
      "selector": "COALESCE(SUM(CASE WHEN cpf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN cpf.clicks ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "clicks",
      "description": "Ad clicks for this subtype bucket over the period.",
      "filterTags": [
        "report_group:cpc"
      ]
    },
    "impressions": {
      "key": "impressions",
      "selector": "COALESCE(SUM(CASE WHEN cpf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN cpf.impressions ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "impressions",
      "description": "Ad impressions for this subtype bucket over the period.",
      "filterTags": [
        "report_group:cpc"
      ]
    },
    "program_gmv": {
      "key": "program_gmv",
      "selector": "COALESCE(SUM(CASE WHEN cpf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN cpf.program_per_click_timestamp_sales ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "program_gmv",
      "description": "Program GMV (per-click-timestamp sales) attributed to this subtype bucket over the period.",
      "filterTags": [
        "report_group:cpc"
      ]
    },
    "program_orders": {
      "key": "program_orders",
      "selector": "COALESCE(SUM(CASE WHEN cpf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN cpf.program_per_click_timestamp_conversions_multi_channel_onsite_offsite ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "program_orders",
      "description": "Program orders (per-click-timestamp multi-channel onsite+offsite conversions) attributed to this subtype bucket over the period.",
      "filterTags": [
        "report_group:cpc"
      ]
    },
    "cpc": {
      "key": "cpc",
      "selector": "COALESCE(ROUND(SAFE_DIVIDE(SUM(CASE WHEN cpf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN cpf.cost ELSE 0 END), NULLIF(SUM(CASE WHEN cpf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN cpf.clicks ELSE 0 END), 0)), 4), 0)",
      "type": "FLOAT",
      "externalColumnName": "cpc",
      "description": "Cost per click = spend / clicks for this subtype bucket.",
      "filterTags": [
        "report_group:cpc"
      ]
    }
  },
  "dateRanges": {
    "count": 1,
    "dataAvailabilityDays": 90,
    "maxDataFetchDaysDuration": 31
  },
  "query": {
    "REPORTING": "SELECT __ATTRIBUTES__, __METRICS__ FROM `prj-onlinesales-prod-01.reporting.campaign_performance_facts` AS cpf JOIN `prj-onlinesales-prod-01.reporting.clients` AS cl ON cl.client_id = cpf.client_id AND cl.agency_id = '__AGENCY_ID__' JOIN `prj-onlinesales-prod-01.reporting.campaign_tagging_data` AS ctd ON ctd.account_id = cpf.account_id AND ctd.campaign_id = cpf.campaign_id AND ctd.client_id = cpf.client_id JOIN `prj-onlinesales-prod-01.reporting.marketing_campaign_group_dimensions` AS g ON g.client_id = ctd.client_id AND g.marketing_campaign_group_id = ctd.marketing_campaign_group_id WHERE cpf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' AND LOWER(g.campaign_type) = 'performance' AND g.campaign_subtype IS NOT NULL AND __FILTER__ GROUP BY __ATTRIBUTES_GROUP_BY__;",
    "MERCHANT": "",
    "GROUPED": ""
  },
  "application": "irisTestApplication"
}

{
  "reportType": "INTERNAL_PERF_CTR_OVERALL",
  "externalReportType": "CTR_OVERALL_REPORT",
  "visibility": "INTERNAL_PERFORMANCE",
  "filterTags": [
    "report_group:ctr"
  ],
  "externalRequiredFilters": [],
  "description": "Marketplace-level CTR for a single period from monetize_merchant_facts: total ad clicks, impressions, click-through rate (clicks*100/impressions), and marketplace-currency spend, as one ungrouped row for the whole marketplace. Optionally scoped to specific merchants via a merchant filter.",
  "source": "GOOGLE_BIG_QUERY",
  "sourceInfo": {
    "appKey": "GCP_BQ_KAM_CREDENTIALS"
  },
  "cacheInfo": {
    "isCachingEnabled": true,
    "cachingExpiryInSec": 900
  },
  "attributes": {},
  "metrics": {
    "clicks": {
      "key": "clicks",
      "selector": "COALESCE(SUM(CASE WHEN mmf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN mmf.clicks ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "clicks",
      "description": "Total ad clicks for the marketplace over the period.",
      "filterTags": [
        "report_group:ctr"
      ]
    },
    "impressions": {
      "key": "impressions",
      "selector": "COALESCE(SUM(CASE WHEN mmf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN mmf.impressions ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "impressions",
      "description": "Total ad impressions for the marketplace over the period.",
      "filterTags": [
        "report_group:ctr"
      ]
    },
    "ctr": {
      "key": "ctr",
      "selector": "COALESCE(SAFE_DIVIDE(SUM(CASE WHEN mmf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN mmf.clicks ELSE 0 END) * 100, SUM(CASE WHEN mmf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN mmf.impressions ELSE 0 END)), 0)",
      "type": "FLOAT",
      "externalColumnName": "ctr",
      "description": "Click-through rate = clicks * 100 / impressions for the marketplace over the period (0 when impressions = 0).",
      "filterTags": [
        "report_group:ctr"
      ]
    },
    "spend": {
      "key": "spend",
      "selector": "COALESCE(SUM(CASE WHEN mmf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN mmf.cost ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "spend",
      "description": "Total ad spend for the marketplace over the period, in the marketplace currency.",
      "filterTags": [
        "report_group:ctr"
      ]
    }
  },
  "dateRanges": {
    "count": 1,
    "dataAvailabilityDays": 90,
    "maxDataFetchDaysDuration": 31
  },
  "query": {
    "REPORTING": "SELECT __METRICS__ FROM `prj-onlinesales-prod-01.reporting.monetize_merchant_facts` AS mmf WHERE mmf.agency_id = '__AGENCY_ID__' AND mmf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' AND __FILTER__;",
    "MERCHANT": "",
    "GROUPED": ""
  },
  "application": "irisTestApplication"
}

{
  "reportType": "INTERNAL_PERF_SEARCH_QUERY_MATCH",
  "externalReportType": "SEARCH_QUERY_MATCH_PERFORMANCE_REPORT",
  "visibility": "INTERNAL_PERFORMANCE",
  "filterTags": [
    "report_group:search_query",
    "report_group:ctr"
  ],
  "externalRequiredFilters": [
    "os_client_id",
    "campaign_id"
  ],
  "description": "Per-(search_query x matched_keyword x keyword_match_type) ad performance inside specific advertiser campaign(s) over one period: raw ad spend, impressions, clicks, and top-of-search impressions. Scoped to given advertiser os_client_id(s) and marketing campaign_id(s); optionally filter by search_query. CTR / CPC / CPM and top-of-search impression share are derived downstream from these raw aggregates.",
  "source": "GOOGLE_BIG_QUERY",
  "sourceInfo": {
    "appKey": "GCP_BQ_KAM_CREDENTIALS"
  },
  "cacheInfo": {
    "isCachingEnabled": true,
    "cachingExpiryInSec": 900
  },
  "attributes": {
    "search_query": {
      "key": "search_query",
      "selector": "LOWER(r.search_query)",
      "type": "STRING",
      "externalColumnName": "search_query",
      "description": "The search term the user typed (lowercased). Optional filter to scope to specific queries.",
      "filterTags": [
        "report_group:search_query",
        "report_group:ctr"
      ]
    },
    "matched_keyword": {
      "key": "matched_keyword",
      "selector": "r.matched_keyword",
      "type": "STRING",
      "externalColumnName": "matched_keyword",
      "description": "The targeted keyword that matched the search query.",
      "filterTags": [
        "report_group:search_query",
        "report_group:ctr"
      ]
    },
    "keyword_match_type": {
      "key": "keyword_match_type",
      "selector": "r.keyword_match_type",
      "type": "STRING",
      "externalColumnName": "keyword_match_type",
      "description": "Match type by which the keyword matched the search query (EXACT / PHRASE / BROAD / ...).",
      "filterTags": [
        "report_group:search_query",
        "report_group:ctr"
      ]
    },
    "os_client_id": {
      "key": "os_client_id",
      "selector": "r.client_id",
      "type": "STRING",
      "externalColumnName": "os_client_id",
      "description": "Advertiser client_id. Mandatory filter: one or more advertiser client_ids to scope the report to.",
      "filterTags": [
        "report_group:search_query",
        "report_group:ctr"
      ]
    },
    "campaign_id": {
      "key": "campaign_id",
      "selector": "LOWER(mcd.marketing_campaign_id)",
      "type": "STRING",
      "externalColumnName": "campaign_id",
      "description": "Marketing campaign_id (lowercased). Mandatory filter: one or more marketing campaign_ids to scope the report to.",
      "filterTags": [
        "report_group:search_query",
        "report_group:ctr"
      ]
    }
  },
  "metrics": {
    "spend": {
      "key": "spend",
      "selector": "COALESCE(SUM(CASE WHEN r.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN r.cost ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "spend",
      "description": "Ad spend for this search_query x keyword x match_type over the period (raw cost from the report; the legacy source does not currency-convert this metric).",
      "filterTags": [
        "report_group:search_query",
        "report_group:ctr"
      ]
    },
    "impressions": {
      "key": "impressions",
      "selector": "COALESCE(SUM(CASE WHEN r.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN r.impressions ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "impressions",
      "description": "Ad impressions served for this search_query x keyword x match_type.",
      "filterTags": [
        "report_group:search_query",
        "report_group:ctr"
      ]
    },
    "clicks": {
      "key": "clicks",
      "selector": "COALESCE(SUM(CASE WHEN r.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN r.clicks ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "clicks",
      "description": "Ad clicks (visits) for this search_query x keyword x match_type.",
      "filterTags": [
        "report_group:search_query",
        "report_group:ctr"
      ]
    },
    "top_of_search_impressions": {
      "key": "top_of_search_impressions",
      "selector": "COALESCE(SUM(CASE WHEN r.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN (CASE WHEN a.is_impression_ad_position_enabled = TRUE THEN r.top_position_search_impressions ELSE r.top_search_keyword_impressions END) ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "top_of_search_impressions",
      "description": "Impressions served in the top-of-search position. Uses top_position_search_impressions when the agency has is_impression_ad_position_enabled, else top_search_keyword_impressions. Top-of-search share (= top_of_search_impressions / impressions) is derived downstream.",
      "filterTags": [
        "report_group:search_query",
        "report_group:ctr"
      ]
    }
  },
  "dateRanges": {
    "count": 1,
    "dataAvailabilityDays": 90,
    "maxDataFetchDaysDuration": 31
  },
  "query": {
    "REPORTING": "SELECT __ATTRIBUTES__, __METRICS__ FROM `prj-onlinesales-prod-01.reporting.os_ads_search_query_performance_report` AS r INNER JOIN `prj-onlinesales-prod-01.reporting.campaign_tagging_data` AS ctd ON ctd.client_id = r.client_id AND ctd.account_id = r.account_id AND ctd.campaign_id = r.campaign_id INNER JOIN `prj-onlinesales-prod-01.reporting.marketing_campaign_dimensions` AS mcd ON ctd.client_id = mcd.client_id AND ctd.marketing_campaign_id = mcd.marketing_campaign_id INNER JOIN `prj-onlinesales-prod-01.reporting.agencies` AS a ON a.marketplace_client_id = r.marketplace_client_id WHERE a.agency_id = '__AGENCY_ID__' AND r.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' AND (mcd.campaign_origin != 'PACKAGE_BASED' OR mcd.campaign_origin IS NULL) AND __FILTER__ GROUP BY __ATTRIBUTES_GROUP_BY__;",
    "MERCHANT": "",
    "GROUPED": ""
  },
  "application": "irisTestApplication"
}

