    "campaign_id": {
      "key": "campaign_id",
      "selector": "impr.campaign_id",
      "type": "STRING",
      "externalColumnName": "campaign_id",
      "description": "Campaign that served the SKU. Optional per-call filter; not required to return rows.",
      "filterTags": [
        "report_group:irrelevancy",
        "report_group:sku"
      ]
    }
  },
  "metrics": {
    "spend": {
      "key": "spend",
      "selector": "COALESCE(SUM(CASE WHEN DATE(TIMESTAMP(impr.response_timestamp_utc), '__SP_TIMEZONE__') BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN COALESCE(impr.bid, 0) * scc.conversion_factor ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "spend",
      "description": "Ad spend on the served SKU for the keyword, converted to the marketplace currency (bid * conversion_factor).",
      "filterTags": [
        "report_group:irrelevancy",
        "report_group:sku"
      ]
    },
    "impressions": {
      "key": "impressions",
      "selector": "COALESCE(SUM(CASE WHEN DATE(TIMESTAMP(impr.response_timestamp_utc), '__SP_TIMEZONE__') BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' AND impr.unique_impressions > 0 THEN 1 ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "impressions",
      "description": "Number of responses for this SKU/keyword that rendered at least one unique impression.",
      "filterTags": [
        "report_group:irrelevancy",
        "report_group:sku"
      ]
    }
  },
  "dateRanges": {
    "count": 1,
    "dataAvailabilityDays": 90,
    "maxDataFetchDaysDuration": 31
  },
  "query": {
    "REPORTING": "SELECT __ATTRIBUTES__, __METRICS__ FROM `prj-onlinesales-prod-01.reporting.os_product_ads_response_to_impressions_mapping` AS impr JOIN `prj-onlinesales-prod-01.reporting.marketplace_clients` AS mc ON mc.marketplace_client_id = impr.marketplace_client_id JOIN `prj-onlinesales-prod-01.reporting.oltp_merchandise_product_dimensions___SP_MARKETPLACE_CLIENT_ID__` AS mpd ON mpd.sku_id = impr.sku_id LEFT JOIN `prj-onlinesales-prod-01.reporting.static_currency_conversion` AS scc ON scc.from_currency = 'USD' AND scc.to_currency = mc.currency WHERE mc.agency_id = '__AGENCY_ID__' AND mc.marketplace_client_id = '__SP_MARKETPLACE_CLIENT_ID__' AND DATE(TIMESTAMP(impr.response_timestamp_utc), '__SP_TIMEZONE__') BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' AND impr.page_type = 'SEARCH' AND __FILTER__ GROUP BY __ATTRIBUTES_GROUP_BY__;",
    "MERCHANT": "",
    "GROUPED": ""
  },
  "application": "irisTestApplication"
}

{
  "reportType": "INTERNAL_PERF_SEARCH_QUERY_REQUESTS_PLA",
  "externalReportType": "SEARCH_QUERY_REQUESTS_PLA_REPORT",
  "visibility": "INTERNAL_PERFORMANCE",
  "filterTags": [
    "report_group:rr",
    "report_group:search_query",
    "report_group:keyword"
  ],
  "externalRequiredFilters": [],
  "description": "Per-keyword PLA ad request / response volume and response rate on search pages for a marketplace over a period, from the timezone-aware search-query request report (dates are converted to the marketplace timezone). One row per keyword. Replaces the three keyword-request reports: use requests + responses + response_rate for keyword-level RR, requests + responses for the Pareto / zero-vs-partial-response buckets, and requests + days_with_requests to judge whether a keyword has enough demand to warrant a campaign. Filter keyword NOT IN ('') to drop requests that carried no search query; use a metrics filter on requests to apply a minimum-volume threshold.",
  "source": "GOOGLE_BIG_QUERY",
  "sourceInfo": {
    "appKey": "GCP_BQ_KAM_CREDENTIALS"
  },
  "cacheInfo": {
    "isCachingEnabled": true,
    "cachingExpiryInSec": 900
  },
  "attributes": {
    "keyword": {
      "key": "keyword",
      "selector": "LOWER(TRIM(r.search_query, '[],\",'))",
      "type": "STRING",
      "externalColumnName": "keyword",
      "description": "The normalized search query (keyword) users typed, lower-cased and stripped of bracket/quote characters.",
      "filterTags": [
        "report_group:rr",
        "report_group:search_query",
        "report_group:keyword"
      ]
    }
  },
  "metrics": {
    "requests": {
      "key": "requests",
      "selector": "COALESCE(SUM(CASE WHEN DATE(TIMESTAMP(r.date, 'UTC'), '__SP_TIMEZONE__') BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN r.request ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "requests",
      "description": "Total ad requests received for this keyword on search pages over the period.",
      "filterTags": [
        "report_group:rr",
        "report_group:search_query",
        "report_group:keyword"
      ]
    },
    "responses": {
      "key": "responses",
      "selector": "COALESCE(SUM(CASE WHEN DATE(TIMESTAMP(r.date, 'UTC'), '__SP_TIMEZONE__') BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN r.response ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "responses",
      "description": "Total ad responses (non-empty fills) served for this keyword on search pages over the period.",
      "filterTags": [
        "report_group:rr",
        "report_group:search_query",
        "report_group:keyword"
      ]
    },
    "response_rate": {
      "key": "response_rate",
      "selector": "SAFE_DIVIDE(COALESCE(SUM(CASE WHEN DATE(TIMESTAMP(r.date, 'UTC'), '__SP_TIMEZONE__') BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN r.response ELSE 0 END), 0) * 100, NULLIF(COALESCE(SUM(CASE WHEN DATE(TIMESTAMP(r.date, 'UTC'), '__SP_TIMEZONE__') BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN r.request ELSE 0 END), 0), 0))",
      "type": "FLOAT",
      "externalColumnName": "response_rate",
      "description": "Response rate for this keyword (responses * 100 / requests) on search pages over the period.",
      "filterTags": [
        "report_group:rr",
        "report_group:search_query",
        "report_group:keyword"
      ]
    },
    "days_with_requests": {
      "key": "days_with_requests",
      "selector": "COUNT(DISTINCT CASE WHEN DATE(TIMESTAMP(r.date, 'UTC'), '__SP_TIMEZONE__') BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN DATE(TIMESTAMP(r.date, 'UTC'), '__SP_TIMEZONE__') END)",
      "type": "FLOAT",
      "externalColumnName": "days_with_requests",
      "description": "Number of distinct days (in the marketplace timezone) on which this keyword received at least one request.",
      "filterTags": [
        "report_group:rr",
        "report_group:search_query",
        "report_group:keyword"
      ]
    }
  },
  "dateRanges": {
    "count": 1,
    "dataAvailabilityDays": 90,
    "maxDataFetchDaysDuration": 31
  },
  "query": {
    "REPORTING": "SELECT __ATTRIBUTES__, __METRICS__ FROM `prj-onlinesales-prod-01.reporting.os_product_ads_search_query_request_report` AS r JOIN `prj-onlinesales-prod-01.reporting.marketplace_clients` AS mc ON r.marketplace_client_id = mc.marketplace_client_id WHERE mc.agency_id = '__AGENCY_ID__' AND DATE(TIMESTAMP(r.date, 'UTC'), '__SP_TIMEZONE__') BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' AND __FILTER__ GROUP BY __ATTRIBUTES_GROUP_BY__;",
    "MERCHANT": "",
    "GROUPED": ""
  },
  "application": "irisTestApplication"
}

{
  "reportType": "INTERNAL_PERF_GMV_ATTRIBUTION",
  "externalReportType": "GMV_ATTRIBUTION_REPORT",
  "visibility": "INTERNAL_PERFORMANCE",
  "filterTags": [
    "report_group:roas",
    "report_group:bu"
  ],
  "externalRequiredFilters": [],
  "description": "Marketplace-level PROGRAM (ad-attributed) vs SITE (organic) funnel for a single period: a one-row aggregate across every seller of the agency. PROGRAM metrics come from per-click-timestamp attribution in client_vendor_channel_performance_facts; SITE metrics are correlated subqueries over monetize_merchant_facts. Spend and revenue are converted to the marketplace currency. Request `spend` alone for the total program-spend check. NOTE: `channel` is a FILTER-ONLY attribute -- this template has no __ATTRIBUTES__ placeholder, so channel can be filtered (PLA = os_product_ads, Display = guaranteed_display_ads / auction_display_ads) but never grouped by. The report is single-period; fetch current and baseline separately.",
  "source": "GOOGLE_BIG_QUERY",
  "sourceInfo": {
    "appKey": "GCP_BQ_KAM_CREDENTIALS"
  },
  "cacheInfo": {
    "isCachingEnabled": true,
    "cachingExpiryInSec": 900
  },
  "attributes": {
    "channel": {
      "key": "channel",
      "selector": "cvcpf.channel",
      "type": "STRING",
      "externalColumnName": "channel",
      "description": "Program (ad) channel: os_product_ads (PLA), guaranteed_display_ads / auction_display_ads (Display). Use as a filter to scope the PROGRAM attribution to a program type; SITE (organic) metrics are unaffected.",
      "filterTags": [
        "report_group:roas",
        "report_group:bu"
      ]
    }
  },
  "metrics": {
    "spend": {
      "key": "spend",
      "selector": "COALESCE(SUM(CASE WHEN cvcpf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN cvcpf.cost * scc.conversion_factor ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "spend",
      "description": "Total program (advertising) spend over the period, converted to the marketplace currency.",
      "filterTags": [
        "report_group:roas",
        "report_group:bu"
      ]
    },
    "impressions": {
      "key": "impressions",
      "selector": "COALESCE(SUM(CASE WHEN cvcpf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN cvcpf.impressions ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "impressions",
      "description": "Program ad impressions over the period.",
      "filterTags": [
        "report_group:roas",
        "report_group:bu"
      ]
    },
    "clicks": {
      "key": "clicks",
      "selector": "COALESCE(SUM(CASE WHEN cvcpf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN cvcpf.clicks ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "clicks",
      "description": "Program ad clicks over the period.",
      "filterTags": [
        "report_group:roas",
        "report_group:bu"
      ]
    },
    "program_gmv": {
      "key": "program_gmv",
      "selector": "COALESCE(SUM(CASE WHEN cvcpf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN cvcpf.program_per_click_timestamp_sales ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "program_gmv",
      "description": "Ad-attributed GMV (program sales), per-click-timestamp attribution, in source units.",
      "filterTags": [
        "report_group:roas",
        "report_group:bu"
      ]
    },
    "program_orders": {
      "key": "program_orders",
      "selector": "COALESCE(SUM(CASE WHEN cvcpf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN cvcpf.program_per_click_timestamp_conversions ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "program_orders",
      "description": "Ad-attributed orders (program conversions), per-click-timestamp attribution.",
      "filterTags": [
        "report_group:roas",
        "report_group:bu"
      ]
    },
    "program_viewproducts": {
      "key": "program_viewproducts",
      "selector": "COALESCE(SUM(CASE WHEN cvcpf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN cvcpf.program_per_click_timestamp_viewproduct ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "program_viewproducts",
      "description": "Ad-attributed product views (program view-product events), per-click-timestamp attribution.",
      "filterTags": [
        "report_group:roas",
        "report_group:bu"
      ]
    },
    "program_add2carts": {
      "key": "program_add2carts",
      "selector": "COALESCE(SUM(CASE WHEN cvcpf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN cvcpf.program_per_click_timestamp_add_to_cart ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "program_add2carts",
      "description": "Ad-attributed add-to-cart events (program), per-click-timestamp attribution.",
      "filterTags": [
        "report_group:roas",
        "report_group:bu"
      ]
    },
    "site_revenue": {
      "key": "site_revenue",
      "selector": "COALESCE((SELECT SUM(mmf.total_sok_sales_usd * scc2.conversion_factor) FROM `prj-onlinesales-prod-01.reporting.monetize_merchant_facts` AS mmf INNER JOIN `prj-onlinesales-prod-01.reporting.marketplace_clients` AS mc2 ON mmf.agency_id = mc2.agency_id AND mmf.marketplace_client_id = mc2.marketplace_client_id INNER JOIN `prj-onlinesales-prod-01.reporting.static_currency_conversion` AS scc2 ON scc2.from_currency = 'USD' AND scc2.to_currency = mc2.currency WHERE mmf.agency_id = '__AGENCY_ID__' AND mmf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__'), 0)",
      "type": "FLOAT",
      "externalColumnName": "site_revenue",
      "description": "Total organic site GMV (total SOK sales) over the period, converted to the marketplace currency.",
      "filterTags": [
        "report_group:roas",
        "report_group:bu"
      ]
    },
    "site_orders": {
      "key": "site_orders",
      "selector": "COALESCE((SELECT SUM(mmf.total_sok_salecompletes) FROM `prj-onlinesales-prod-01.reporting.monetize_merchant_facts` AS mmf INNER JOIN `prj-onlinesales-prod-01.reporting.marketplace_clients` AS mc2 ON mmf.agency_id = mc2.agency_id AND mmf.marketplace_client_id = mc2.marketplace_client_id INNER JOIN `prj-onlinesales-prod-01.reporting.static_currency_conversion` AS scc2 ON scc2.from_currency = 'USD' AND scc2.to_currency = mc2.currency WHERE mmf.agency_id = '__AGENCY_ID__' AND mmf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__'), 0)",
      "type": "FLOAT",
      "externalColumnName": "site_orders",
      "description": "Total organic site orders (total SOK sale-completes) over the period.",
      "filterTags": [
        "report_group:roas",
        "report_group:bu"
      ]
    },
    "site_viewproducts": {
      "key": "site_viewproducts",
      "selector": "COALESCE((SELECT SUM(mmf.total_sok_viewproducts) FROM `prj-onlinesales-prod-01.reporting.monetize_merchant_facts` AS mmf INNER JOIN `prj-onlinesales-prod-01.reporting.marketplace_clients` AS mc2 ON mmf.agency_id = mc2.agency_id AND mmf.marketplace_client_id = mc2.marketplace_client_id INNER JOIN `prj-onlinesales-prod-01.reporting.static_currency_conversion` AS scc2 ON scc2.from_currency = 'USD' AND scc2.to_currency = mc2.currency WHERE mmf.agency_id = '__AGENCY_ID__' AND mmf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__'), 0)",
      "type": "FLOAT",
      "externalColumnName": "site_viewproducts",
      "description": "Total organic site product views (total SOK view-products) over the period.",
      "filterTags": [
        "report_group:roas",
        "report_group:bu"
      ]
    },
    "site_add2carts": {
      "key": "site_add2carts",
      "selector": "COALESCE((SELECT SUM(mmf.total_sok_add2carts) FROM `prj-onlinesales-prod-01.reporting.monetize_merchant_facts` AS mmf INNER JOIN `prj-onlinesales-prod-01.reporting.marketplace_clients` AS mc2 ON mmf.agency_id = mc2.agency_id AND mmf.marketplace_client_id = mc2.marketplace_client_id INNER JOIN `prj-onlinesales-prod-01.reporting.static_currency_conversion` AS scc2 ON scc2.from_currency = 'USD' AND scc2.to_currency = mc2.currency WHERE mmf.agency_id = '__AGENCY_ID__' AND mmf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__'), 0)",
      "type": "FLOAT",
      "externalColumnName": "site_add2carts",
      "description": "Total organic site add-to-cart events (total SOK add2carts) over the period.",
      "filterTags": [
        "report_group:roas",
        "report_group:bu"
      ]
    }
  },
  "dateRanges": {
    "count": 1,
    "dataAvailabilityDays": 90,
    "maxDataFetchDaysDuration": 31
  },
  "query": {
    "REPORTING": "SELECT __METRICS__ FROM `prj-onlinesales-prod-01.reporting.client_vendor_channel_performance_facts` AS cvcpf INNER JOIN `prj-onlinesales-prod-01.reporting.clients` AS clients ON clients.client_id = cvcpf.client_id AND clients.agency_id = '__AGENCY_ID__' INNER JOIN `prj-onlinesales-prod-01.reporting.marketplace_clients` AS mc ON mc.agency_id = clients.agency_id AND clients.client_id != mc.marketplace_client_id INNER JOIN `prj-onlinesales-prod-01.reporting.static_currency_conversion` AS scc ON scc.from_currency = cvcpf.currency AND scc.to_currency = mc.currency WHERE cvcpf.vendor = 'os_ads' AND cvcpf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' AND __FILTER__;",
    "MERCHANT": "",
    "GROUPED": ""
  },
  "application": "irisTestApplication"
}

{
  "reportType": "INTERNAL_PERF_DAILY_ORDER_TRENDS",
  "externalReportType": "DAILY_ORDER_TRENDS_REPORT",
  "visibility": "INTERNAL_PERFORMANCE",
  "filterTags": [
    "report_group:roas"
  ],
  "externalRequiredFilters": [],
  "description": "Date-level PROGRAM (ad-attributed, per-click-timestamp CONVERTED conversions/sales) vs SITE (organic, monetize_merchant_facts converted) funnel for a marketplace, one row per date. Program side: spend, clicks, program_orders, program_gmv, program_viewproducts, program_add2carts. Site side: site_orders, site_revenue, site_viewproducts, site_add2carts. organic_orders = site_orders - program_orders. Money is converted to the marketplace currency. Filter by channel to isolate PLA (os_product_ads) vs Display (guaranteed_display_ads / auction_display_ads) on the program side.",
  "source": "GOOGLE_BIG_QUERY",
  "sourceInfo": {
    "appKey": "GCP_BQ_KAM_CREDENTIALS"
  },
  "cacheInfo": {
    "isCachingEnabled": true,
    "cachingExpiryInSec": 900
  },
  "attributes": {
    "date": {
      "key": "date",
      "selector": "COALESCE(s.date, p.date)",
      "type": "STRING",
      "externalColumnName": "date",
      "description": "Calendar date of the daily program-vs-site funnel row (from either the program or site aggregate).",
      "filterTags": [
        "report_group:roas"
      ]
    },
    "channel": {
      "key": "channel",
      "selector": "cvcpf.channel",
      "type": "STRING",
      "externalColumnName": "channel",
      "description": "Program ad channel: os_product_ads (PLA), guaranteed_display_ads / auction_display_ads (Display). Use as a per-call FILTER (not a group-by) to scope the program side to a program type; it does not affect the organic site side.",
      "filterTags": [
        "report_group:roas"
      ]
    }
  },
  "metrics": {
    "spend": {
      "key": "spend",
      "selector": "COALESCE(SUM(CASE WHEN p.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN p.spend ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "spend",
      "description": "Program (advertising) spend on this date, converted to the marketplace currency.",
      "filterTags": [
        "report_group:roas"
      ]
    },
    "clicks": {
      "key": "clicks",
      "selector": "COALESCE(SUM(CASE WHEN p.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN p.clicks ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "clicks",
      "description": "Program ad clicks on this date.",
      "filterTags": [
        "report_group:roas"
      ]
    },
    "program_orders": {
      "key": "program_orders",
      "selector": "COALESCE(SUM(CASE WHEN p.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN p.program_orders ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "program_orders",
      "description": "Ad-attributed orders on this date (per-click-timestamp CONVERTED conversions).",
      "filterTags": [
        "report_group:roas"
      ]
    },
    "program_gmv": {
      "key": "program_gmv",
      "selector": "COALESCE(SUM(CASE WHEN p.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN p.program_gmv ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "program_gmv",
      "description": "Ad-attributed GMV / sales on this date (per-click-timestamp CONVERTED sales), converted to the marketplace currency.",
      "filterTags": [
        "report_group:roas"
      ]
    },
    "program_viewproducts": {
      "key": "program_viewproducts",
      "selector": "COALESCE(SUM(CASE WHEN p.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN p.program_viewproducts ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "program_viewproducts",
      "description": "Ad-attributed product-page views on this date (per-click-timestamp CONVERTED viewproduct).",
      "filterTags": [
        "report_group:roas"
      ]
    },
    "program_add2carts": {
      "key": "program_add2carts",
      "selector": "COALESCE(SUM(CASE WHEN p.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN p.program_add2carts ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "program_add2carts",
      "description": "Ad-attributed add-to-cart events on this date (per-click-timestamp CONVERTED add_to_cart).",
      "filterTags": [
        "report_group:roas"
      ]
    },
    "site_orders": {
      "key": "site_orders",
      "selector": "COALESCE(SUM(CASE WHEN s.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN s.site_orders ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "site_orders",
      "description": "Total site (organic) completed orders on this date (total_sok_salecompletes).",
      "filterTags": [
        "report_group:roas"
      ]
    },
    "site_revenue": {
      "key": "site_revenue",
      "selector": "COALESCE(SUM(CASE WHEN s.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN s.site_revenue ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "site_revenue",
      "description": "Total site (organic) revenue on this date (total_sok_sales_usd), converted to the marketplace currency.",
      "filterTags": [
        "report_group:roas"
      ]
    },
    "site_viewproducts": {
      "key": "site_viewproducts",
      "selector": "COALESCE(SUM(CASE WHEN s.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN s.site_viewproducts ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "site_viewproducts",
      "description": "Total site (organic) product-page views on this date (total_sok_viewproducts).",
      "filterTags": [
        "report_group:roas"
      ]
    },
    "site_add2carts": {
      "key": "site_add2carts",
      "selector": "COALESCE(SUM(CASE WHEN s.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN s.site_add2carts ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "site_add2carts",
      "description": "Total site (organic) add-to-cart events on this date (total_sok_add2carts).",
      "filterTags": [
        "report_group:roas"
      ]
    },
    "organic_orders": {
      "key": "organic_orders",
      "selector": "COALESCE(SUM(CASE WHEN s.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN s.site_orders ELSE 0 END), 0) - COALESCE(SUM(CASE WHEN p.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN p.program_orders ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "organic_orders",
      "description": "Organic (non-ad-attributed) orders on this date = site_orders - program_orders.",
      "filterTags": [
        "report_group:roas"
      ]
    }
  },
  "dateRanges": {
    "count": 1,
    "dataAvailabilityDays": 90,
    "maxDataFetchDaysDuration": 31
  },
  "query": {
    "REPORTING": "SELECT __ATTRIBUTES__, __METRICS__ FROM (SELECT cvcpf.date AS date, SUM(cvcpf.cost * scc.conversion_factor) AS spend, SUM(cvcpf.clicks) AS clicks, SUM(cvcpf.program_per_click_timestamp_conversions) AS program_orders, SUM(cvcpf.program_per_click_timestamp_sales) AS program_gmv, SUM(cvcpf.program_per_click_timestamp_viewproduct) AS program_viewproducts, SUM(cvcpf.program_per_click_timestamp_add_to_cart) AS program_add2carts FROM `prj-onlinesales-prod-01.reporting.client_vendor_channel_performance_facts` AS cvcpf INNER JOIN `prj-onlinesales-prod-01.reporting.clients` AS clients ON clients.client_id = cvcpf.client_id AND clients.agency_id = '__AGENCY_ID__' INNER JOIN `prj-onlinesales-prod-01.reporting.marketplace_clients` AS mc ON mc.agency_id = clients.agency_id AND clients.client_id != mc.marketplace_client_id INNER JOIN `prj-onlinesales-prod-01.reporting.static_currency_conversion` AS scc ON scc.from_currency = cvcpf.currency AND scc.to_currency = mc.currency WHERE cvcpf.vendor = 'os_ads' AND cvcpf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' AND __FILTER__ GROUP BY 1) AS p FULL OUTER JOIN (SELECT mmf.date AS date, SUM(mmf.total_sok_salecompletes) AS site_orders, SUM(mmf.total_sok_sales_usd * scc.conversion_factor) AS site_revenue, SUM(mmf.total_sok_viewproducts) AS site_viewproducts, SUM(mmf.total_sok_add2carts) AS site_add2carts FROM `prj-onlinesales-prod-01.reporting.monetize_merchant_facts` AS mmf INNER JOIN `prj-onlinesales-prod-01.reporting.marketplace_clients` AS mc ON mmf.agency_id = mc.agency_id AND mmf.marketplace_client_id = mc.marketplace_client_id INNER JOIN `prj-onlinesales-prod-01.reporting.static_currency_conversion` AS scc ON scc.from_currency = 'USD' AND scc.to_currency = mc.currency WHERE mmf.agency_id = '__AGENCY_ID__' AND mmf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' GROUP BY 1) AS s ON p.date = s.date GROUP BY __ATTRIBUTES_GROUP_BY__;",
    "MERCHANT": "",
    "GROUPED": ""
  },
  "application": "irisTestApplication"
}

