      "description": "The display ad unit / placement slot the request was attributed to.",
      "filterTags": [
        "report_group:rr",
        "report_group:search_query"
      ]
    },
    "category_l1": {
      "key": "category_l1",
      "selector": "r.category_l1",
      "type": "STRING",
      "externalColumnName": "category_l1",
      "description": "Top-level (L1) product category the requests/responses were attributed to.",
