        "report_group:rr"
      ]
    },
    "page_type": {
      "key": "page_type",
      "selector": "auf.page_type",
      "type": "STRING",
      "externalColumnName": "page_type",
      "description": "The surface the ad unit served on (SEARCH, CATEGORY, PRODUCT, HOME, ...).",
