      "key": "date",
      "externalColumnName": "date",
      "filterTags": [
        "report_group:bu",
        "report_group:rr"
      ]
    }
  },
  "metrics": {
    "requests": {
      "key": "requests",
      "selector": "COALESCE(SUM(CASE WHEN auf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN auf.requests ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "requests",
      "description": "Ad requests received on this ad unit.",
      "filterTags": [
        "report_group:bu",
        "report_group:rr"
      ]
    },
    "responses": {
      "key": "responses",
      "selector": "COALESCE(SUM(CASE WHEN auf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN auf.non_zero_responses ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "responses",
      "description": "Requests that returned at least one ad (non-zero responses).",
      "filterTags": [
        "report_group:bu",
        "report_group:rr"
      ]
    },
    "response_rate": {
      "selector": "ROUND(SAFE_DIVIDE(SUM(CASE WHEN auf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN auf.non_zero_responses ELSE 0 END) * 100, NULLIF(SUM(CASE WHEN auf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN auf.requests ELSE 0 END), 0)), 2)",
      "type": "FLOAT",
      "description": "Non-zero responses as a percentage of requests for this grouping.",
      "key": "response_rate",
      "externalColumnName": "response_rate",
      "filterTags": [
        "report_group:bu",
        "report_group:rr"
      ]
    },
    "impressions": {
      "key": "impressions",
      "selector": "COALESCE(SUM(CASE WHEN auf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN auf.impressions ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "impressions",
      "description": "Ad impressions served on this ad unit.",
