        "report_group:bu",
        "report_group:rr"
      ]
    },
    "clicks": {
      "key": "clicks",
      "selector": "COALESCE(SUM(CASE WHEN auf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN auf.clicks ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "clicks",
      "description": "Ad clicks on this ad unit.",
      "filterTags": [
        "report_group:bu",
        "report_group:rr"
      ]
    },
    "spend": {
      "key": "spend",
      "selector": "COALESCE(SUM(CASE WHEN auf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN auf.cost * scc.conversion_factor ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "spend",
      "description": "Ad spend on this ad unit, converted to the marketplace currency.",
      "filterTags": [
        "report_group:bu",
        "report_group:rr"
