      "filterTags": [
        "report_group:bu",
        "report_group:rr"
      ]
    },
    "conversions": {
      "key": "conversions",
      "selector": "COALESCE(SUM(CASE WHEN auf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN auf.program_per_click_timestamp_conversions ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "conversions",
      "description": "Conversion funnel events (per-click-timestamp) attributed to this ad unit.",
      "filterTags": [
        "report_group:bu",
        "report_group:rr"
      ]
    }
  },
  "dateRanges": {
    "count": 1,
    "dataAvailabilityDays": 90,
    "maxDataFetchDaysDuration": 31
  },
  "query": {
    "REPORTING": "SELECT __ATTRIBUTES__, __METRICS__ FROM `prj-onlinesales-prod-01.reporting.os_display_ads_ad_unit_facts` AS auf INNER JOIN `prj-onlinesales-prod-01.reporting.marketplace_clients` AS mc ON auf.marketplace_client_id = mc.marketplace_client_id LEFT JOIN `prj-onlinesales-prod-01.reporting.static_currency_conversion` AS scc ON scc.from_currency = 'USD' AND scc.to_currency = mc.currency WHERE mc.agency_id = '__AGENCY_ID__' AND auf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' AND __FILTER__ GROUP BY __ATTRIBUTES_GROUP_BY__;",
