      ]
    },
    "category": {
      "key": "category",
      "selector": "CONCAT(COALESCE(r.category_l1, 'na'), ' > ', COALESCE(r.category_l2, 'na'), ' > ', COALESCE(r.category_l3, 'na'))",
      "type": "STRING",
      "externalColumnName": "category",
