    "response_rate": {
      "key": "response_rate",
      "selector": "SAFE_DIVIDE(SUM(CASE WHEN r.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN r.non_zero_responses ELSE 0 END) * 100, NULLIF(SUM(CASE WHEN r.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN r.requests ELSE 0 END), 0))",
      "type": "FLOAT",
      "externalColumnName": "response_rate",
      "description": "Response rate (%) = non-zero responses / requests * 100 for this dimension grouping.",
      "filterTags": [
