      "selector": "ctd.marketing_campaign_id",
      "type": "STRING",
      "externalColumnName": "campaign_id",
      "description": "Marketing campaign id that responded to the search query.",
      "filterTags": [
        "report_group:search_query",
        "report_group:rr"
      ]
