  ],
  "externalRequiredFilters": [],
  "description": "Per-keyword PLA ad request / response volume and response rate on search pages for a marketplace over a period, from the timezone-aware search-query request report (dates are converted to the marketplace timezone). One row per keyword. Replaces the three keyword-request reports: use requests + responses + response_rate for keyword-level RR, requests + responses for the Pareto / zero-vs-partial-response buckets, and requests + days_with_requests to judge whether a keyword has enough demand to warrant a campaign. Filter keyword NOT IN ('') to drop requests that carried no search query; use a metrics filter on requests to apply a minimum-volume threshold.",
  "source": "GOOGLE_BIG_QUERY",
  "sourceInfo": {
    "appKey": "GCP_BQ_KAM_CREDENTIALS"
  },
  "cacheInfo": {
    "isCachingEnabled": true,
    "cachingExpiryInSec": 900
  },
  "attributes": {
    "keyword": {
      "key": "keyword",
      "selector": "LOWER(TRIM(r.search_query, '[],\",'))",
      "type": "STRING",
      "externalColumnName": "keyword",
      "description": "The normalized search query (keyword) users typed, lower-cased and stripped of bracket/quote characters.",
      "filterTags": [
        "report_group:rr",
        "report_group:search_query",
        "report_group:keyword"
      ]
    }
  },
  "metrics": {
    "requests": {
      "key": "requests",
      "selector": "COALESCE(SUM(CASE WHEN DATE(TIMESTAMP(r.date, 'UTC'), '__SP_TIMEZONE__') BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN r.request ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "requests",
      "description": "Total ad requests received for this keyword on search pages over the period.",
      "filterTags": [
        "report_group:rr",
        "report_group:search_query",
        "report_group:keyword"
      ]
    },
    "responses": {
      "key": "responses",
      "selector": "COALESCE(SUM(CASE WHEN DATE(TIMESTAMP(r.date, 'UTC'), '__SP_TIMEZONE__') BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN r.response ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "responses",
      "description": "Total ad responses (non-empty fills) served for this keyword on search pages over the period.",
      "filterTags": [
        "report_group:rr",
        "report_group:search_query",
        "report_group:keyword"
      ]
    },
    "response_rate": {
      "key": "response_rate",
      "selector": "SAFE_DIVIDE(COALESCE(SUM(CASE WHEN DATE(TIMESTAMP(r.date, 'UTC'), '__SP_TIMEZONE__') BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN r.response ELSE 0 END), 0) * 100, NULLIF(COALESCE(SUM(CASE WHEN DATE(TIMESTAMP(r.date, 'UTC'), '__SP_TIMEZONE__') BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN r.request ELSE 0 END), 0), 0))",
      "type": "FLOAT",
      "externalColumnName": "response_rate",
      "description": "Response rate for this keyword (responses * 100 / requests) on search pages over the period.",
      "filterTags": [
        "report_group:rr",
        "report_group:search_query",
        "report_group:keyword"
      ]
    },
    "days_with_requests": {
      "key": "days_with_requests",
      "selector": "COUNT(DISTINCT CASE WHEN DATE(TIMESTAMP(r.date, 'UTC'), '__SP_TIMEZONE__') BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN DATE(TIMESTAMP(r.date, 'UTC'), '__SP_TIMEZONE__') END)",
      "type": "FLOAT",
      "externalColumnName": "days_with_requests",
      "description": "Number of distinct days (in the marketplace timezone) on which this keyword received at least one request.",
      "filterTags": [
        "report_group:rr",
        "report_group:search_query",
        "report_group:keyword"
      ]
    }
  },
  "dateRanges": {
    "count": 1,
    "dataAvailabilityDays": 90,
    "maxDataFetchDaysDuration": 31
  },
  "query": {
    "REPORTING": "SELECT __ATTRIBUTES__, __METRICS__ FROM `prj-onlinesales-prod-01.reporting.os_product_ads_search_query_request_report` AS r JOIN `prj-onlinesales-prod-01.reporting.marketplace_clients` AS mc ON r.marketplace_client_id = mc.marketplace_client_id WHERE mc.agency_id = '__AGENCY_ID__' AND DATE(TIMESTAMP(r.date, 'UTC'), '__SP_TIMEZONE__') BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' AND __FILTER__ GROUP BY __ATTRIBUTES_GROUP_BY__;",
    "MERCHANT": "",
    "GROUPED": ""
  },
  "application": "irisTestApplication"
}

