    },
    "campaign_group_type": {
      "key": "campaign_group_type",
      "selector": "CASE WHEN JSON_EXTRACT_SCALAR(mcgd.metadata, '$.isEanEnabled') = 'true' AND ctd.vendor IN ('google', 'facebook', 'tiktok') THEN 'Offsite Ad' WHEN mcgd.campaign_type = 'PERFORMANCE' THEN 'Sponsored Product Ad' WHEN mcgd.campaign_type IN ('AWARENESS', 'INVENTORY') THEN 'Sponsored Display Ad' WHEN mcgd.campaign_type IN ('OFFSITE') THEN 'Offsite Ad' ELSE 'Other' END",
      "type": "STRING",
      "externalColumnName": "campaign_group_type",
