      "key": "campaign_subtype",
      "selector": "mcgd.campaign_subtype",
      "type": "STRING",
      "externalColumnName": "campaign_subtype",
      "description": "Raw campaign subtype from marketing_campaign_group_dimensions (e.g. SMART_SHOPPING, OS_ADS_SEARCH, AUCTION).",
      "filterTags": [
        "report_group:campaign"
      ]
    },
    "daily_budget": {
      "key": "daily_budget",
      "selector": "CASE WHEN mcgd.budget_type = 'LIFETIME_BUDGET' THEN NULL ELSE mcgd.daily_budget END",
      "type": "FLOAT",
      "externalColumnName": "daily_budget",
      "description": "Daily budget of the campaign group (NULL when the group uses a LIFETIME_BUDGET). Not currency-converted; in the group's own currency.",
      "filterTags": [
