      ]
    },
    "merchant_name": {
      "key": "merchant_name",
      "selector": "mmd.merchant_name",
      "type": "STRING",
      "externalColumnName": "merchant_name",
      "description": "Seller / merchant display name owning the campaign group.",
      "filterTags": [
        "report_group:campaign"
      ]
