      "selector": "mcd.client_id",
      "type": "STRING",
      "externalColumnName": "os_client_id",
      "description": "OnlineSales client id (the advertiser account). Filterable (legacy client_ids filter).",
      "filterTags": [
        "report_group:campaign"
      ]
    }
  },
  "metrics": {
    "impressions": {
      "key": "impressions",
      "selector": "COALESCE(SUM(CASE WHEN cpf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN cpf.impressions ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "impressions",
      "description": "Ad impressions for the campaign group over the period (raw campaign_performance_facts.impressions).",
      "filterTags": [
        "report_group:campaign"
      ]
    },
    "clicks": {
      "key": "clicks",
      "selector": "COALESCE(SUM(CASE WHEN cpf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN cpf.clicks ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "clicks",
      "description": "Ad clicks for the campaign group over the period (raw campaign_performance_facts.clicks).",
      "filterTags": [
        "report_group:campaign"
      ]
    },
    "spend": {
      "key": "spend",
      "selector": "COALESCE(SUM(CASE WHEN cpf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN cpf.cost * scc.conversion_factor ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "spend",
      "description": "Ad spend (cost) for the campaign group over the period, converted from cpf.currency to the marketplace currency.",
      "filterTags": [
        "report_group:campaign"
      ]
    },
    "orders": {
      "key": "orders",
      "selector": "COALESCE(SUM(CASE WHEN cpf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN cpf.program_per_click_timestamp_conversions ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "orders",
      "description": "Program orders (per-click-timestamp conversions) attributed to the campaign group over the period.",
      "filterTags": [
        "report_group:campaign"
      ]
    },
    "revenue": {
      "key": "revenue",
      "selector": "COALESCE(SUM(CASE WHEN cpf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN cpf.program_per_click_timestamp_sales * scc.conversion_factor ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "revenue",
      "description": "Program revenue / GMV (per-click-timestamp sales) attributed to the campaign group over the period, converted from cpf.currency to the marketplace currency.",
      "filterTags": [
        "report_group:campaign"
      ]
    }
  },
  "dateRanges": {
    "count": 1,
    "dataAvailabilityDays": 90,
    "maxDataFetchDaysDuration": 31
  },
  "query": {
    "REPORTING": "SELECT __ATTRIBUTES__, __METRICS__ FROM `prj-onlinesales-prod-01.reporting.campaign_performance_facts` AS cpf JOIN `prj-onlinesales-prod-01.reporting.campaign_tagging_data` AS ctd ON cpf.campaign_id = ctd.campaign_id AND cpf.client_id = ctd.client_id JOIN `prj-onlinesales-prod-01.reporting.marketing_campaign_dimensions` AS mcd ON ctd.marketing_campaign_id = mcd.marketing_campaign_id AND ctd.client_id = mcd.client_id JOIN `prj-onlinesales-prod-01.reporting.marketing_campaign_group_dimensions` AS mcgd ON mcd.marketing_campaign_group_id = mcgd.marketing_campaign_group_id AND mcd.client_id = mcgd.client_id AND mcgd.marketing_campaign_group_id = ctd.marketing_campaign_group_id AND mcgd.client_id = ctd.client_id JOIN `prj-onlinesales-prod-01.reporting.monetize_merchant_dimensions` AS mmd ON mcgd.client_id = mmd.client_id AND mmd.agency_id = '__AGENCY_ID__' JOIN `prj-onlinesales-prod-01.reporting.marketplace_clients` AS mc ON mc.agency_id = mmd.agency_id AND mc.marketplace_type = 'monetize' JOIN `prj-onlinesales-prod-01.reporting.static_currency_conversion` AS scc ON scc.from_currency = cpf.currency AND scc.to_currency = mc.currency WHERE cpf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' AND (mcgd.campaign_origin != 'PACKAGE_BASED' OR mcgd.campaign_origin IS NULL) AND mmd.merchant_id NOT LIKE 'NULL' AND mc.agency_id = '__AGENCY_ID__' AND __FILTER__ GROUP BY __ATTRIBUTES_GROUP_BY__;",
    "MERCHANT": "",
    "GROUPED": ""
  },
  "application": "irisTestApplication"
}

