      "description": "Program revenue / GMV (per-click-timestamp sales) attributed to the campaign group over the period, converted from cpf.currency to the marketplace currency.",
      "filterTags": [
        "report_group:campaign"
      ]
    }
  },
  "dateRanges": {
    "count": 1,
    "dataAvailabilityDays": 90,
    "maxDataFetchDaysDuration": 31
  },
  "query": {
    "REPORTING": "SELECT __ATTRIBUTES__, __METRICS__ FROM `prj-onlinesales-prod-01.reporting.campaign_performance_facts` AS cpf JOIN `prj-onlinesales-prod-01.reporting.campaign_tagging_data` AS ctd ON cpf.campaign_id = ctd.campaign_id AND cpf.client_id = ctd.client_id JOIN `prj-onlinesales-prod-01.reporting.marketing_campaign_dimensions` AS mcd ON ctd.marketing_campaign_id = mcd.marketing_campaign_id AND ctd.client_id = mcd.client_id JOIN `prj-onlinesales-prod-01.reporting.marketing_campaign_group_dimensions` AS mcgd ON mcd.marketing_campaign_group_id = mcgd.marketing_campaign_group_id AND mcd.client_id = mcgd.client_id AND mcgd.marketing_campaign_group_id = ctd.marketing_campaign_group_id AND mcgd.client_id = ctd.client_id JOIN `prj-onlinesales-prod-01.reporting.monetize_merchant_dimensions` AS mmd ON mcgd.client_id = mmd.client_id AND mmd.agency_id = '__AGENCY_ID__' JOIN `prj-onlinesales-prod-01.reporting.marketplace_clients` AS mc ON mc.agency_id = mmd.agency_id AND mc.marketplace_type = 'monetize' JOIN `prj-onlinesales-prod-01.reporting.static_currency_conversion` AS scc ON scc.from_currency = cpf.currency AND scc.to_currency = mc.currency WHERE cpf.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' AND (mcgd.campaign_origin != 'PACKAGE_BASED' OR mcgd.campaign_origin IS NULL) AND mmd.merchant_id NOT LIKE 'NULL' AND mc.agency_id = '__AGENCY_ID__' AND __FILTER__ GROUP BY __ATTRIBUTES_GROUP_BY__;",
    "MERCHANT": "",
    "GROUPED": ""
  },
  "application": "irisTestApplication"
}

{
  "reportType": "INTERNAL_PERF_CAMPAIGN_PRODUCT_SELECTION",
  "externalReportType": "CAMPAIGN_PRODUCT_SELECTION_REPORT",
  "visibility": "INTERNAL_PERFORMANCE",
  "filterTags": [
    "report_group:campaign"
  ],
  "externalRequiredFilters": [
    "campaign_id"
  ],
  "description": "Currently-active products selected in a specific campaign for a marketplace: one row per selected product with merchant_id, product_id, product_name, availability (e.g. 'in stock'), brand, and category L1/L2/L3. Point-in-time (no date range). campaign_id is a mandatory filter and resolves to campaign_tagging_data.marketing_campaign_id. Only active selections (opaps.is_active = TRUE) on non-deleted product dimensions (ompd.is_deleted = FALSE) are returned; filter availability = 'in stock' to restrict to in-stock products. Source tables are per-marketplace suffixed (os_product_ads_product_selection_<mcid>, oltp_merchandise_product_dimensions_<mcid>). Python layer derives product list, category_l1 breakdown, category hierarchy, and summary counts (total/in-stock products, unique brands and categories).",
  "source": "GOOGLE_BIG_QUERY",
  "sourceInfo": {
    "appKey": "GCP_BQ_KAM_CREDENTIALS"
  },
  "cacheInfo": {
    "isCachingEnabled": true,
    "cachingExpiryInSec": 900
  },
  "attributes": {
    "campaign_id": {
      "key": "campaign_id",
      "selector": "SAFE_CAST(ctd.marketing_campaign_id AS STRING)",
      "type": "STRING",
      "externalColumnName": "campaign_id",
      "description": "The marketing_campaign_id the caller holds. Mandatory filter: pass the campaign's marketing_campaign_id here; campaign_tagging_data resolves it to the internal campaign whose active product selection is returned.",
      "filterTags": [
        "report_group:campaign"
      ]
    },
    "merchant_id": {
      "key": "merchant_id",
      "selector": "SAFE_CAST(opaps.merchant_id AS STRING)",
      "type": "STRING",
      "externalColumnName": "merchant_id",
      "description": "Merchant (seller) that owns the selected product.",
      "filterTags": [
        "report_group:campaign"
      ]
    },
    "product_id": {
      "key": "product_id",
      "selector": "SAFE_CAST(opaps.product_id AS STRING)",
      "type": "STRING",
      "externalColumnName": "product_id",
      "description": "Product / SKU id selected in the campaign (joins to the product-dimension sku_id).",
      "filterTags": [
        "report_group:campaign"
      ]
    },
    "product_name": {
      "key": "product_name",
      "selector": "ompd.e_name",
      "type": "STRING",
      "externalColumnName": "product_name",
      "description": "Display name of the product (product-dimension e_name).",
      "filterTags": [
        "report_group:campaign"
      ]
    },
    "availability": {
      "key": "availability",
      "selector": "ompd.e_availability",
      "type": "STRING",
      "externalColumnName": "availability",
      "description": "Stock availability of the product (e.g. 'in stock', 'out of stock'). Filter availability = 'in stock' to restrict to in-stock products.",
      "filterTags": [
        "report_group:campaign"
      ]
    },
    "brand": {
      "key": "brand",
      "selector": "ompd.e_brand",
      "type": "STRING",
      "externalColumnName": "brand",
      "description": "Brand of the product (product-dimension e_brand).",
      "filterTags": [
        "report_group:campaign"
      ]
    },
    "category_l1": {
      "key": "category_l1",
      "selector": "ompd.category_l1",
      "type": "STRING",
      "externalColumnName": "category_l1",
      "description": "Level-1 (top) product category.",
      "filterTags": [
        "report_group:campaign"
      ]
    },
    "category_l2": {
      "key": "category_l2",
      "selector": "ompd.category_l2",
      "type": "STRING",
      "externalColumnName": "category_l2",
      "description": "Level-2 product category (may be null when only L1 is present).",
      "filterTags": [
        "report_group:campaign"
      ]
    },
    "category_l3": {
      "key": "category_l3",
      "selector": "ompd.category_l3",
      "type": "STRING",
      "externalColumnName": "category_l3",
      "description": "Level-3 (leaf) product category (may be null when only L1/L2 are present).",
      "filterTags": [
        "report_group:campaign"
      ]
    }
  },
  "metrics": {
    "placeholder_metric": {
      "key": "placeholder_metric",
      "selector": "0",
      "type": "FLOAT",
      "externalColumnName": "placeholder_metric",
      "description": "Constant 0. Row-level product-selection passthrough with no aggregated measure; KAM requires at least one metric to fetch.",
      "filterTags": [
        "report_group:campaign"
      ]
    }
  },
  "dateRanges": {
    "count": 1,
    "dataAvailabilityDays": 90,
    "maxDataFetchDaysDuration": 31
  },
  "query": {
    "REPORTING": "SELECT __ATTRIBUTES__, __METRICS__ FROM `prj-onlinesales-prod-01.reporting.os_product_ads_product_selection___SP_MARKETPLACE_CLIENT_ID__` AS opaps INNER JOIN `prj-onlinesales-prod-01.reporting.campaign_tagging_data` AS ctd ON SAFE_CAST(opaps.campaign_id AS STRING) = SAFE_CAST(ctd.campaign_id AS STRING) AND SAFE_CAST(opaps.account_id AS STRING) = SAFE_CAST(ctd.account_id AS STRING) INNER JOIN `prj-onlinesales-prod-01.reporting.oltp_merchandise_product_dimensions___SP_MARKETPLACE_CLIENT_ID__` AS ompd ON SAFE_CAST(opaps.product_id AS STRING) = SAFE_CAST(ompd.sku_id AS STRING) AND SAFE_CAST(opaps.merchant_id AS STRING) = SAFE_CAST(ompd.merchant_id AS STRING) AND SAFE_CAST(opaps.client_id AS STRING) = SAFE_CAST(ompd.client_id AS STRING) WHERE ompd.is_deleted = FALSE AND opaps.is_active = TRUE AND __FILTER__ GROUP BY __ATTRIBUTES_GROUP_BY__;",
    "MERCHANT": "",
    "GROUPED": ""
  },
  "application": "irisTestApplication"
}

