      "selector": "mmd.merchant_id",
      "type": "STRING",
      "externalColumnName": "merchant_id",
      "description": "Merchant id that owns the campaign.",
      "filterTags": [
        "report_group:category",
        "report_group:campaign"
      ]
    },
    "os_client_id": {
      "key": "os_client_id",
      "selector": "cte.client_id",
      "type": "STRING",
      "externalColumnName": "os_client_id",
      "description": "OnlineSales client id (advertiser account) the campaign belongs to.",
      "filterTags": [
        "report_group:category",
        "report_group:campaign"
      ]
    },
    "campaign_id": {
      "key": "campaign_id",
      "selector": "cte.marketing_campaign_id",
      "type": "STRING",
      "externalColumnName": "campaign_id",
      "description": "Marketing campaign id competing in the category.",
      "filterTags": [
        "report_group:category",
        "report_group:campaign"
      ]
    },
    "category_l1": {
      "key": "category_l1",
      "selector": "cte.category_l1",
      "type": "STRING",
      "externalColumnName": "category_l1",
      "description": "Top-level (L1) product category the campaign's spend/products were attributed to. Per-call filter to scope to one category.",
      "filterTags": [
        "report_group:category",
        "report_group:campaign"
      ]
    },
    "category_l2": {
      "key": "category_l2",
      "selector": "cte.category_l2",
      "type": "STRING",
      "externalColumnName": "category_l2",
      "description": "Second-level (L2) product category. Per-call filter to scope to one category.",
      "filterTags": [
        "report_group:category",
        "report_group:campaign"
      ]
    },
    "category_l3": {
      "key": "category_l3",
      "selector": "cte.category_l3",
      "type": "STRING",
      "externalColumnName": "category_l3",
      "description": "Third-level (L3) product category. Per-call filter to scope to one category.",
      "filterTags": [
        "report_group:category",
        "report_group:campaign"
      ]
    },
    "campaign_group_name": {
      "key": "campaign_group_name",
      "selector": "mcgd.marketing_campaign_group_alias",
      "type": "STRING",
      "externalColumnName": "campaign_group_name",
      "description": "Human-readable alias of the campaign group the campaign belongs to.",
      "filterTags": [
        "report_group:category",
        "report_group:campaign"
      ]
    },
    "campaign_group_status": {
      "key": "campaign_group_status",
      "selector": "REPLACE(mcgd.effective_status, '_', ' ')",
      "type": "STRING",
      "externalColumnName": "campaign_group_status",
      "description": "Effective status of the campaign group (e.g. 'ACTIVE', 'PAUSED'), underscores replaced with spaces.",
      "filterTags": [
        "report_group:category",
        "report_group:campaign"
      ]
    },
    "campaign_group_daily_budget": {
      "key": "campaign_group_daily_budget",
      "selector": "mcgd.daily_budget",
      "type": "FLOAT",
      "externalColumnName": "campaign_group_daily_budget",
      "description": "Daily budget configured on the campaign group (raw, as stored on the dimension; not category-scoped).",
      "filterTags": [
        "report_group:category",
        "report_group:campaign"
      ]
    },
    "campaign_subtype": {
      "key": "campaign_subtype",
      "selector": "LOWER(mcgd.campaign_subtype)",
      "type": "STRING",
      "externalColumnName": "campaign_subtype",
      "description": "Campaign subtype (lower-cased), e.g. 'auction', 'block_buy', 'pre_auction'.",
      "filterTags": [
        "report_group:category",
        "report_group:campaign"
      ]
    },
    "bidding_strategy_type": {
      "key": "bidding_strategy_type",
      "selector": "CASE WHEN (mcd.campaign_type = 'PERFORMANCE' AND mcd.objective_name IN ('Visitors', 'Visibility') AND mcd.bidding_strategy = 'AUTO_CPC') THEN 'Max Performance CPC' WHEN (mcd.campaign_type = 'PERFORMANCE' AND mcd.objective_name IN ('Visitors', 'Visibility') AND mcd.bidding_strategy = 'AUTO_CPM') THEN 'Max Performance CPM' WHEN (mcd.campaign_type = 'PERFORMANCE' AND mcd.objective_name IN ('Visitors', 'Visibility') AND mcd.bidding_strategy IN ('CPM', 'CPC')) THEN mcd.bidding_strategy WHEN mcd.campaign_type IN ('INVENTORY', 'AWARENESS') AND mcd.campaign_subtype = 'PRE_AUCTION' THEN 'NA' WHEN mcd.objective_name IN ('Absolute Revenue') THEN 'ROI' WHEN mcd.objective_name IN ('Visibility', 'Reach') AND mcd.campaign_subtype = 'AUCTION' THEN UPPER(JSON_EXTRACT_SCALAR(REPLACE(mcd.campaign_setting_metadata, '\"\"', '\"'), '$.bidding_strategy_type')) WHEN mcd.objective_name IN ('Visibility', 'Reach') AND mcd.campaign_subtype = 'BLOCK_BUY' AND JSON_EXTRACT_SCALAR(REPLACE(mcd.campaign_setting_metadata, '\"\"', '\"'), '$.bidding_strategy_type') = 'CPM' THEN 'Fixed CPM' WHEN mcd.objective_name IN ('Visibility', 'Reach') AND mcd.campaign_subtype = 'BLOCK_BUY' AND JSON_EXTRACT_SCALAR(REPLACE(mcd.campaign_setting_metadata, '\"\"', '\"'), '$.bidding_strategy_type') = 'CPD' THEN 'CPD' ELSE 'UNKNOWN' END",
      "type": "STRING",
      "externalColumnName": "bidding_strategy_type",
      "description": "Derived bid model for the campaign group (CPC / CPM / Max Performance CPC / Max Performance CPM / ROI / Fixed CPM / CPD / NA / UNKNOWN), computed from campaign_type + objective_name + bidding_strategy + campaign_subtype + the bidding_strategy_type JSON inside campaign_setting_metadata.",
      "filterTags": [
        "report_group:category",
        "report_group:campaign"
      ]
    }
  },
  "metrics": {
    "spend": {
      "key": "spend",
      "selector": "ROUND(SUM(cte.cost), 2)",
      "type": "FLOAT",
      "externalColumnName": "spend",
      "description": "Category-level ad spend for the campaign over the period, converted to the marketplace currency.",
      "filterTags": [
        "report_group:category",
        "report_group:campaign"
      ]
    },
    "cpc": {
      "key": "cpc",
      "selector": "ROUND(CASE WHEN SUM(cte.clicks) > 0 THEN SUM(cte.cost) / SUM(cte.clicks) ELSE 0 END, 2)",
      "type": "FLOAT",
      "externalColumnName": "cpc",
      "description": "Category-level cost-per-click for the campaign (converted spend / clicks) over the period.",
      "filterTags": [
        "report_group:category",
        "report_group:campaign"
      ]
    },
    "cpm": {
      "key": "cpm",
      "selector": "ROUND(CASE WHEN SUM(cte.impressions) > 0 THEN (SUM(cte.cost) * 1000) / SUM(cte.impressions) ELSE 0 END, 2)",
      "type": "FLOAT",
      "externalColumnName": "cpm",
      "description": "Category-level cost-per-mille for the campaign (converted spend * 1000 / impressions) over the period.",
      "filterTags": [
        "report_group:category",
        "report_group:campaign"
      ]
    }
  },
  "dateRanges": {
    "count": 1,
    "dataAvailabilityDays": 90,
    "maxDataFetchDaysDuration": 31
  },
  "query": {
    "REPORTING": "SELECT __ATTRIBUTES__, __METRICS__ FROM (SELECT opacrp_raw.merchant_id, opacrp_raw.client_id, opacrp_raw.marketing_campaign_id, opacrp_raw.category_l1, opacrp_raw.category_l2, opacrp_raw.category_l3, SUM(opacrp_raw.cost * scc.conversion_factor) AS cost, SUM(opacrp_raw.clicks) AS clicks, SUM(opacrp_raw.impressions) AS impressions FROM `prj-onlinesales-prod-01.reporting.os_product_ads_campaign_category_report_pla` AS opacrp_raw INNER JOIN `prj-onlinesales-prod-01.reporting.agencies` AS agencies ON agencies.marketplace_client_id = opacrp_raw.marketplace_client_id LEFT JOIN `prj-onlinesales-prod-01.reporting.static_currency_conversion` AS scc ON scc.from_currency = 'USD' AND scc.to_currency = agencies.currency WHERE agencies.agency_id = '__AGENCY_ID__' AND opacrp_raw.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' GROUP BY opacrp_raw.merchant_id, opacrp_raw.client_id, opacrp_raw.marketing_campaign_id, opacrp_raw.category_l1, opacrp_raw.category_l2, opacrp_raw.category_l3 HAVING SUM(opacrp_raw.product_count) > 0 OR SUM(opacrp_raw.cost) > 0) AS cte INNER JOIN `prj-onlinesales-prod-01.reporting.marketing_campaign_dimensions` AS mcd ON mcd.client_id = cte.client_id AND mcd.marketing_campaign_id = cte.marketing_campaign_id INNER JOIN `prj-onlinesales-prod-01.reporting.marketing_campaign_group_dimensions` AS mcgd ON mcgd.client_id = cte.client_id AND mcgd.marketing_campaign_group_id = mcd.marketing_campaign_group_id INNER JOIN `prj-onlinesales-prod-01.reporting.monetize_merchant_dimensions` AS mmd ON LOWER(mmd.merchant_id) = LOWER(cte.merchant_id) AND mmd.agency_id = '__AGENCY_ID__' WHERE mmd.agency_id = '__AGENCY_ID__' AND (mcd.campaign_origin != 'PACKAGE_BASED' OR mcd.campaign_origin IS NULL) AND __FILTER__ GROUP BY __ATTRIBUTES_GROUP_BY__;",
    "MERCHANT": "",
    "GROUPED": ""
  },
  "application": "irisTestApplication"
}

{
