      "selector": "ctd.marketing_campaign_id",
      "type": "STRING",
      "externalColumnName": "marketing_campaign_id",
      "description": "Marketing campaign id (working id for internal analysis).",
      "filterTags": [
        "report_group:merchant_breakdown",
        "report_group:category"
      ]
    },
    "marketing_campaign_group_id": {
      "key": "marketing_campaign_group_id",
      "selector": "ctd.marketing_campaign_group_id",
      "type": "STRING",
      "externalColumnName": "marketing_campaign_group_id",
      "description": "Marketing campaign group id (working id for internal analysis).",
      "filterTags": [
        "report_group:merchant_breakdown",
        "report_group:category"
      ]
    },
    "os_client_id": {
      "key": "os_client_id",
      "selector": "f.client_id",
      "type": "STRING",
