      ]
    }
  },
  "metrics": {
    "spend": {
      "key": "spend",
      "selector": "COALESCE(SUM(CASE WHEN f.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN f.cost ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "spend",
      "description": "PLA ad spend for this category x campaign (raw cost, not currency-converted).",
