      "selector": "COALESCE(SUM(CASE WHEN f.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN f.clicks ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "clicks",
      "description": "PLA ad clicks for this category x campaign.",
      "filterTags": [
        "report_group:merchant_breakdown",
        "report_group:category"
      ]
    },
    "orders": {
      "key": "orders",
      "selector": "COALESCE(SUM(CASE WHEN f.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN f.program_per_click_timestamp_conversions ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "orders",
      "description": "Ad-attributed orders / conversions (per-click-timestamp) for this category x campaign.",
