  },
  "dateRanges": {
    "count": 1,
    "dataAvailabilityDays": 90,
    "maxDataFetchDaysDuration": 31
  },
  "query": {
    "REPORTING": "SELECT __ATTRIBUTES__, __METRICS__ FROM `prj-onlinesales-prod-01.reporting.merchant_merchandise_product_dimensions` AS mmpd JOIN `prj-onlinesales-prod-01.reporting.os_product_ads_device_product_facts` AS f ON f.client_id = mmpd.client_id AND f.sku_id = mmpd.sku_id LEFT JOIN `prj-onlinesales-prod-01.reporting.campaign_tagging_data` AS ctd ON ctd.account_id = f.account_id AND ctd.campaign_id = f.campaign_id AND ctd.client_id = f.client_id JOIN `prj-onlinesales-prod-01.reporting.marketing_campaign_dimensions` AS mcd ON ctd.marketing_campaign_id = mcd.marketing_campaign_id AND mcd.client_id = f.client_id AND mcd.campaign_origin != 'PACKAGE_BASED' JOIN `prj-onlinesales-prod-01.reporting.marketing_campaign_group_dimensions` AS mcgd ON ctd.client_id = mcgd.client_id AND ctd.marketing_campaign_group_id = mcgd.marketing_campaign_group_id JOIN `prj-onlinesales-prod-01.reporting.clients` AS c ON c.client_id = f.client_id WHERE c.agency_id = '__AGENCY_ID__' AND f.date >= '__START_DATE_1__' AND f.date <= '__END_DATE_1__' AND LOWER(mcgd.campaign_type) IN ('performance') AND LOWER(mcgd.campaign_subtype) IN ('os_ads_search', 'smart_shopping') AND __FILTER__ GROUP BY __ATTRIBUTES_GROUP_BY__;",
    "MERCHANT": "",
    "GROUPED": ""
  },
  "application": "irisTestApplication"
}

